/**
 * Bundled, source-cited starter quotations.
 *
 * Every entry is a direct excerpt from a public-domain edition named in its
 * source field. Biblical passages use creator: 'Unknown' because traditional
 * authorship is not certain. This is application data only: it is never
 * written to IndexedDB or synchronized with Supabase.
 */
export type StarterQuote = Readonly<{
  id: string;
  text: string;
  creator: string;
  source: string;
}>;

export const starterQuotes: readonly StarterQuote[] = [
  { id: 'starter-0001', text: "Self-love is the greatest of flatterers.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 2 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0002', text: "Whatever discoveries have been made in the region of self-love, there remain many unexplored territories there.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 3 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0003', text: "Self love is more cunning than the most cunning man in the world.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 4 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0004', text: "The duration of our passions is no more dependant upon us than the duration of our life.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 5 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0005', text: "Passion often renders the most clever man a fool, and even sometimes renders the most foolish man clever.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 6 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0006', text: "Great and striking actions which dazzle the eyes are represented by politicians as the effect of great designs, instead of which they are commonly caused by the temper and the passions. Thus the war between Augustus and Anthony, which is set down to the ambition they entertained of making themselves masters of the world, was probably but an effect of jealousy.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 7 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0007', text: "The passions are the only advocates which always persuade. They are a natural art, the rules of which are infallible; and the simplest man with passion will be more persuasive than the most eloquent without.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 8 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0008', text: "The passions possess a certain injustice and self interest which makes it dangerous to follow them, and in reality we should distrust them even when they appear most trustworthy.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 9 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0009', text: "In the human heart there is a perpetual generation of passions; so that the ruin of one is almost always the foundation of another.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 10 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0010', text: "Passions often produce their contraries: avarice sometimes leads to prodigality, and prodigality to avarice; we are often obstinate through weakness and daring though timidity.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 11 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0011', text: "Whatever care we take to conceal our passions under the appearances of piety and honour, they are always to be seen through these veils.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 12 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0012', text: "Our self love endures more impatiently the condemnation of our tastes than of our opinions.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 13 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0013', text: "Men are not only prone to forget benefits and injuries; they even hate those who have obliged them, and cease to hate those who have injured them. The necessity of revenging an injury or of recompensing a benefit seems a slavery to which they are unwilling to submit.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 14 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0014', text: "The clemency of Princes is often but policy to win the affections of the people.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 15 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0015', text: "This clemency of which they make a merit, arises oftentimes from vanity, sometimes from idleness, oftentimes from fear, and almost always from all three combined.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 16 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0016', text: "The moderation of those who are happy arises from the calm which good fortune bestows upon their temper.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 17 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0017', text: "Moderation is caused by the fear of exciting the envy and contempt which those merit who are intoxicated with their good fortune; it is a vain display of our strength of mind, and in short the moderation of men at their greatest height is only a desire to appear greater than their fortune.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 18 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0018', text: "We have all sufficient strength to support the misfortunes of others.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 19 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0019', text: "The constancy of the wise is only the talent of concealing the agitation of their hearts.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 20 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0020', text: "Those who are condemned to death affect sometimes a constancy and contempt for death which is only the fear of facing it; so that one may say that this constancy and contempt are to their mind what the bandage is to their eyes.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 21 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0021', text: "Philosophy triumphs easily over past evils and future evils; but present evils triumph over it.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 22 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0022', text: "Few people know death, we only endure it, usually from determination, and even from stupidity and custom; and most men only die because they know not how to prevent dying.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 23 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0023', text: "When great men permit themselves to be cast down by the continuance of misfortune, they show us that they were only sustained by ambition, and not by their mind; so that PLUS a great vanity, heroes are made like other men.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 24 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0024', text: "We need greater virtues to sustain good than evil fortune. {The quotation wrongly had \"does\" for \"doth\".}", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 25 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0025', text: "Neither the sun nor death can be looked at without winking.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 26 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0026', text: "People are often vain of their passions, even of the worst, but envy is a passion so timid and shame-faced that no one ever dare avow her.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 27 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0027', text: "Jealousy is in a manner just and reasonable, as it tends to preserve a good which belongs, or which we believe belongs to us, on the other hand envy is a fury which cannot endure the happiness of others.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 28 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0028', text: "The evil that we do does not attract to us so much persecution and hatred as our good qualities.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 29 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0029', text: "We have more strength than will; and it is often merely for an excuse we say things are impossible.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 30 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0030', text: "If we had no faults we should not take so much pleasure in noting those of others.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 31 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0031', text: "Jealousy lives upon doubt; and comes to an end or becomes a fury as soon as it passes from doubt to certainty.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 32 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0032', text: "Pride indemnifies itself and loses nothing even when it casts away vanity.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 33 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0033', text: "If we had no pride we should not complain of that of others.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 34 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0034', text: "Pride is much the same in all men, the only difference is the method and manner of showing it.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 35 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0035', text: "It would seem that nature, which has so wisely ordered the organs of our body for our happiness, has also given us pride to spare us the mortification of knowing our imperfections.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 36 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0036', text: "Pride has a larger part than goodness in our remonstrances with those who commit faults, and we reprove them not so much to correct as to persuade them that we ourselves are free from faults.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 37 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0037', text: "We promise according to our hopes; we perform according to our fears.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 38 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0038', text: "Interest speaks all sorts of tongues and plays all sorts of characters; even that of disinterestedness.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 39 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0039', text: "Interest blinds some and makes some see.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 40 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0040', text: "Those who apply themselves too closely to little things often become incapable of great things.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 41 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0041', text: "We have not enough strength to follow all our reason.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 42 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0042', text: "A man often believes himself leader when he is led; as his mind endeavours to reach one goal, his heart insensibly drags him towards another.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 43 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0043', text: "Strength and weakness of mind are mis-named; they are really only the good or happy arrangement of our bodily organs.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 44 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0044', text: "The caprice of our temper is even more whimsical than that of Fortune.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 45 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0045', text: "The attachment or indifference which philosophers have shown to life is only the style of their self love, about which we can no more dispute than of that of the palate or of the choice of colours.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 46 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0046', text: "Our temper sets a price upon every gift that we receive from fortune.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 47 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0047', text: "Happiness is in the taste, and not in the things themselves; we are happy from possessing what we like, not from possessing what others like.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 48 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0048', text: "We are never so happy or so unhappy as we suppose.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 49 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0049', text: "Those who think they have merit persuade themselves that they are honoured by being unhappy, in order to persuade others and themselves that they are worthy to be the butt of fortune. {The translators' incorrectly cite Speech On Conciliation With America. Also, Burke does not actually write \"Ambition has been...\", he writes \"It has been...\" when speaking of ambition.}", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 50 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0050', text: "Nothing should so much diminish the satisfaction which we feel with ourselves as seeing that we disapprove at one time of that which we approve of at another.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 51 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0051', text: "Whatever difference there appears in our fortunes, there is nevertheless a certain compensation of good and evil which renders them equal.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 52 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0052', text: "Whatever great advantages nature may give, it is not she alone, but fortune also that makes the hero.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 53 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0053', text: "The contempt of riches in philosophers was only a hidden desire to avenge their merit upon the injustice of fortune, by despising the very goods of which fortune had deprived them; it was a secret to guard themselves against the degradation of poverty, it was a back way by which to arrive at that distinction which they could not gain by riches.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 54 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0054', text: "The hate of favourites is only a love of favour. The envy of NOT possessing it, consoles and softens its regrets by the contempt it evinces for those who possess it, and we refuse them our homage, not being able to detract from them what attracts that of the rest of the world.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 55 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0055', text: "To establish ourselves in the world we do everything to appear as if we were established.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 56 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0056', text: "Although men flatter themselves with their great actions, they are not so often the result of a great design as of chance.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 57 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0057', text: "It would seem that our actions have lucky or unlucky stars to which they owe a great part of the blame or praise which is given them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 58 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0058', text: "There are no accidents so unfortunate from which skilful men will not draw some advantage, nor so fortunate that foolish men will not turn them to their hurt.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 59 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0059', text: "Fortune turns all things to the advantage of those on whom she smiles.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 60 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0060', text: "The happiness or unhappiness of men depends no less upon their dispositions than their fortunes.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 61 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0061', text: "Sincerity is an openness of heart; we find it in very few people; what we usually see is only an artful dissimulation to win the confidence of others.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 62 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0062', text: "The aversion to lying is often a hidden ambition to render our words credible and weighty, and to attach a religious aspect to our conversation.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 63 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0063', text: "Truth does not do as much good in the world, as its counterfeits do evil.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 64 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0064', text: "There is no praise we have not lavished upon Prudence; and yet she cannot assure to us the most trifling event.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 65 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0065', text: "A clever man ought to so regulate his interests that each will fall in due order. Our greediness so often troubles us, making us run after so many things at the same time, that while we too eagerly look after the least we miss the greatest.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 66 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0066', text: "What grace is to the body good sense is to the mind.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 67 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0067', text: "It is difficult to define love; all we can say is, that in the soul it is a desire to rule, in the mind it is a sympathy, and in the body it is a hidden and delicate wish to possess what we love--Plus many mysteries. {Two notes about this quotation: (1) the translators' mistakenly have \"singularity\" for the first \"singularly\" and (2) Hobbes does not actually write \"Love is the...\"--he writes \"Love of one...\" under the heading \"The passion of Love.\"}", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 68 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0068', text: "If there is a pure love, exempt from the mixture of our other passions, it is that which is concealed at the bottom of the heart and of which even ourselves are ignorant.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 69 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0069', text: "There is no disguise which can long hide love where it exists, nor feign it where it does not.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 70 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0070', text: "There are few people who would not be ashamed of being beloved when they love no longer.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 71 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0071', text: "If we judge of love by the majority of its results it rather resembles hatred than friendship.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 72 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0072', text: "We may find women who have never indulged in an intrigue, but it is rare to find those who have intrigued but once.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 73 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0073', text: "There is only one sort of love, but there are a thousand different copies.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 74 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0074', text: "Neither love nor fire can subsist without perpetual motion; both cease to live so soon as they cease to hope, or to fear.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 75 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0075', text: "There is real love just as there are real ghosts; every person speaks of it, few persons have seen it.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 76 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0076', text: "Love lends its name to an infinite number of engagements (Commerces) which are attributed to it, but with which it has no more concern than the Doge has with all that is done in Venice.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 77 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0077', text: "The love of justice is simply in the majority of men the fear of suffering injustice.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 78 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0078', text: "Silence is the best resolve for him who distrusts himself.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 79 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0079', text: "What renders us so changeable in our friendship is, that it is difficult to know the qualities of the soul, but easy to know those of the mind.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 80 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0080', text: "We can love nothing but what agrees with us, and we can only follow our taste or our pleasure when we prefer our friends to ourselves; nevertheless it is only by that preference that friendship can be true and perfect.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 81 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0081', text: "Reconciliation with our enemies is but a desire to better our condition, a weariness of war, the fear of some unlucky accident.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 82 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0082', text: "What men term friendship is merely a partnership with a collection of reciprocal interests, and an exchange of favours--in fact it is but a trade in which self love always expects to gain something.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 83 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0083', text: "It is more disgraceful to distrust than to be deceived by our friends.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 84 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0084', text: "We often persuade ourselves to love people who are more powerful than we are, yet interest alone produces our friendship; we do not give our hearts away for the good we wish to do, but for that we expect to receive.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 85 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0085', text: "Our distrust of another justifies his deceit.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 86 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0086', text: "Men would not live long in society were they not the dupes of each other.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 87 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0087', text: "Self love increases or diminishes for us the good qualities of our friends, in proportion to the satisfaction we feel with them, and we judge of their merit by the manner in which they act towards us.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 88 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0088', text: "Everyone blames his memory, no one blames his judgment.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 89 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0089', text: "In the intercourse of life, we please more by our faults than by our good qualities.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 90 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0090', text: "The largest ambition has the least appearance of ambition when it meets with an absolute impossibility in compassing its object.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 91 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0091', text: "To awaken a man who is deceived as to his own merit is to do him as bad a turn as that done to the Athenian madman who was happy in believing that all the ships touching at the port belonged to him.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 92 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0092', text: "Old men delight in giving good advice as a consolation for the fact that they can no longer set bad examples.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 93 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0093', text: "Great names degrade instead of elevating those who know not how to sustain them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 94 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0094', text: "The test of extraordinary merit is to see those who envy it the most yet obliged to praise it.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 95 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0095', text: "A man is perhaps ungrateful, but often less chargeable with ingratitude than his benefactor is.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 96 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0096', text: "We are deceived if we think that mind and judgment are two different matters: judgment is but the extent of the light of the mind. This light penetrates to the bottom of matters; it remarks all that can be remarked, and perceives what appears imperceptible. Therefore we must agree that it is the extent of the light in the mind that produces all the effects which we attribute to judgment.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 97 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0097', text: "Everyone praises his heart, none dare praise their understanding.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 98 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0098', text: "Politeness of mind consists in thinking chaste and refined thoughts.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 99 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0099', text: "Gallantry of mind is saying the most empty things in an agreeable manner.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 100 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0100', text: "Ideas often flash across our minds more complete than we could make them after much labour.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 101 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0101', text: "The head is ever the dupe of the heart.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 102 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0102', text: "Those who know their minds do not necessarily know their hearts.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 103 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0103', text: "Men and things have each their proper perspective; to judge rightly of some it is necessary to see them near, of others we can never judge rightly but at a distance.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 104 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0104', text: "A man for whom accident discovers sense, is not a rational being. A man only is so who understands, who distinguishes, who tests it.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 105 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0105', text: "To understand matters rightly we should understand their details, and as that knowledge is almost infinite, our knowledge is always superficial and imperfect.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 106 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0106', text: "One kind of flirtation is to boast we never flirt.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 107 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0107', text: "The head cannot long play the part of the heart.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 108 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0108', text: "Youth changes its tastes by the warmth of its blood, age retains its tastes by habit.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 109 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0109', text: "Nothing is given so profusely as advice.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 110 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0110', text: "The more we love a woman the more prone we are to hate her.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 111 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0111', text: "The blemishes of the mind, like those of the face, increase by age.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 112 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0112', text: "There may be good but there are no pleasant marriages.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 113 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0113', text: "We are inconsolable at being deceived by our enemies and betrayed by our friends, yet still we are often content to be thus served by ourselves.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 114 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0114', text: "It is as easy unwittingly to deceive oneself as to deceive others.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 115 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0115', text: "Nothing is less sincere than the way of asking and giving advice. The person asking seems to pay deference to the opinion of his friend, while thinking in reality of making his friend approve his opinion and be responsible for his conduct. The person giving the advice returns the confidence placed in him by eager and disinterested zeal, in doing which he is usually guided only by his own interest or reputation.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 116 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0116', text: "The most subtle of our acts is to simulate blindness for snares that we know are set for us. We are never so easily deceived as when trying to deceive.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 117 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0117', text: "The intention of never deceiving often exposes us to deception.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 118 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0118', text: "We become so accustomed to disguise ourselves to others that at last we are disguised to ourselves. {The translators' incorrectly cite Thoughts On The Cause Of The Present Discontents.}", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 119 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0119', text: "We often act treacherously more from weakness than from a fixed motive.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 120 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0120', text: "We frequently do good to enable us with impunity to do evil.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 121 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0121', text: "If we conquer our passions it is more from their weakness than from our strength.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 122 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0122', text: "If we never flattered ourselves we should have but scant pleasure.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 123 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0123', text: "The most deceitful persons spend their lives in blaming deceit, so as to use it on some great occasion to promote some great interest.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 124 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0124', text: "The daily employment of cunning marks a little mind, it generally happens that those who resort to it in one respect to protect themselves lay themselves open to attack in another.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 125 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0125', text: "Cunning and treachery are the offspring of incapacity.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 126 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0126', text: "The true way to be deceived is to think oneself more knowing than others.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 127 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0127', text: "Too great cleverness is but deceptive delicacy, true delicacy is the most substantial cleverness.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 128 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0128', text: "It is sometimes necessary to play the fool to avoid being deceived by cunning men.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 129 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0129', text: "Weakness is the only fault which cannot be cured.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 130 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0130', text: "The smallest fault of women who give themselves up to love is to love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 131 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0131', text: "It is far easier to be wise for others than to be so for oneself.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 132 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0132', text: "The only good examples are those, that make us see the absurdity of bad originals.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 133 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0133', text: "We are never so ridiculous from the habits we have as from those that we affect to have.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 134 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0134', text: "We sometimes differ more widely from ourselves than we do from others.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 135 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0135', text: "There are some who never would have loved if they never had heard it spoken of.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 136 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0136', text: "When not prompted by vanity we say little.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 137 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0137', text: "A man would rather say evil of himself than say nothing.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 138 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0138', text: "If it was not for the company of fools, a witty man would often be greatly at a loss.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 140 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0139', text: "We often boast that we are never bored, but yet we are so conceited that we do not perceive how often we bore others.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 141 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0140', text: "As it is the mark of great minds to say many things in a few words, so it is that of little minds to use many words to say nothing.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 142 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0141', text: "It is oftener by the estimation of our own feelings that we exaggerate the good qualities of others than by their merit, and when we praise them we wish to attract their praise.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 143 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0142', text: "We do not like to praise, and we never praise without a motive. Praise is flattery, artful, hidden, delicate, which gratifies differently him who praises and him who is praised. The one takes it as the reward of merit, the other bestows it to show his impartiality and knowledge.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 144 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0143', text: "We often select envenomed praise which, by a reaction upon those we praise, shows faults we could not have shown by other means.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 145 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0144', text: "Usually we only praise to be praised.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 146 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0145', text: "Few are sufficiently wise to prefer censure which is useful to praise which is treacherous.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 147 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0146', text: "Some reproaches praise; some praises reproach.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 148 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0147', text: "The refusal of praise is only the wish to be praised twice.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 149 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0148', text: "The desire which urges us to deserve praise strengthens our good qualities, and praise given to wit, valour, and beauty, tends to increase them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 150 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0149', text: "It is easier to govern others than to prevent being governed.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 151 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0150', text: "If we never flattered ourselves the flattery of others would not hurt us.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 152 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0151', text: "Nature makes merit but fortune sets it to work.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 153 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0152', text: "Fortune cures us of many faults that reason could not.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 154 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0153', text: "There are some persons who only disgust with their abilities, there are persons who please even with their faults.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 155 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0154', text: "There are persons whose only merit consists in saying and doing stupid things at the right time, and who ruin all if they change their manners.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 156 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0155', text: "The fame of great men ought always to be estimated by the means used to acquire it.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 157 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0156', text: "Flattery is base coin to which only our vanity gives currency.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 158 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0157', text: "It is not enough to have great qualities, we should also have the management of them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 159 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0158', text: "However brilliant an action it should not be esteemed great unless the result of a great motive.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 160 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0159', text: "A certain harmony should be kept between actions and ideas if we desire to estimate the effects that they produce.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 161 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0160', text: "The art of using moderate abilities to advantage wins praise, and often acquires more reputation than real brilliancy.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 162 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0161', text: "Numberless arts appear foolish whose secre{t} motives are most wise and weighty.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 163 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0162', text: "It is much easier to seem fitted for posts we do not fill than for those we do.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 164 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0163', text: "Ability wins us the esteem of the true men, luck that of the people.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 165 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0164', text: "The world oftener rewards the appearance of merit than merit itself.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 166 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0165', text: "Avarice is more opposed to economy than to liberality.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 167 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0166', text: "However deceitful hope may be, yet she carries us on pleasantly to the end of life.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 168 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0167', text: "Idleness and fear keeps us in the path of duty, but our virtue often gets the praise.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 169 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0168', text: "If one acts rightly and honestly, it is difficult to decide whether it is the effect of integrity or skill.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 170 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0169', text: "As rivers are lost in the sea so are virtues in self.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 171 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0170', text: "If we thoroughly consider the varied effects of indifference we find we miscarry more in our duties than in our interests.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 172 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0171', text: "There are different kinds of curiosity: one springs from interest, which makes us desire to know everything that may be profitable to us; another from pride, which springs from a desire of knowing what others are ignorant of.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 173 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0172', text: "It is far better to accustom our mind to bear the ills we have than to speculate on those which may befall us.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 174 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0173', text: "Constancy in love is a perpetual inconstancy which causes our heart to attach itself to all the qualities of the person we love in succession, sometimes giving the preference to one, sometimes to another. This constancy is merely inconstancy fixed, and limited to the same person.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 175 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0174', text: "There are two kinds of constancy in love, one arising from incessantly finding in the loved one fresh objects to love, the other from regarding it as a point of honour to be constant.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 176 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0175', text: "Perseverance is not deserving of blame or praise, as it is merely the continuance of tastes and feelings which we can neither create or destroy.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 177 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0176', text: "What makes us like new studies is not so much the weariness we have of the old or the wish for change as the desire to be admired by those who know more than ourselves, and the hope of advantage over those who know less.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 178 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0177', text: "We sometimes complain of the levity of our friends to justify our own by anticipation.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 179 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0178', text: "Our repentance is not so much sorrow for the ill we have done as fear of the ill that may happen to us.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 180 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0179', text: "One sort of inconstancy springs from levity or weakness of mind, and makes us accept everyone's opinion, and another more excusable comes from a surfeit of matter.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 181 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0180', text: "Vices enter into the composition of virtues as poison into that of medicines. Prudence collects and blends the two and renders them useful against the ills of life.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 182 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0181', text: "For the credit of virtue we must admit that the greatest misfortunes of men are those into which they fall through their crimes.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 183 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0182', text: "We admit our faults to repair by our sincerity the evil we have done in the opinion of others.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 184 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0183', text: "There are both heroes of evil and heroes of good.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 185 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0184', text: "We do not despise all who have vices, but we do despise all who have not virtues.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 186 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0185', text: "The name of virtue is as useful to our interest as that of vice.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 187 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0186', text: "The health of the mind is not less uncertain than that of the body, and when passions seem furthest removed we are no less in danger of infection than of falling ill when we are well.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 188 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0187', text: "It seems that nature has at man's birth fixed the bounds of his virtues and vices.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 189 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0188', text: "Great men should not have great faults.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 190 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0189', text: "We may say vices wait on us in the course of our life as the landlords with whom we successively lodge, and if we travelled the road twice over I doubt if our experience would make us avoid them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 191 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0190', text: "When our vices leave us we flatter ourselves with the idea we have left them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 192 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0191', text: "There are relapses in the diseases of the mind as in those of the body; what we call a cure is often no more than an intermission or change of disease.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 193 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0192', text: "The defects of the mind are like the wounds of the body. Whatever care we take to heal them the scars ever remain, and there is always danger of their reopening.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 194 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0193', text: "The reason which often prevents us abandoning a single vice is having so many.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 195 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0194', text: "We easily forget those faults which are known only to ourselves.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 196 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0195', text: "There are men of whom we can never believe evil without having seen it. Yet there are very few in whom we should be surprised to see it.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 197 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0196', text: "We exaggerate the glory of some men to detract from that of others, and we should praise Prince Conde and Marshal Turenne much less if we did not want to blame them both.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 198 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0197', text: "The desire to appear clever often prevents our being so.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 199 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0198', text: "Virtue would not go far did not vanity escort her.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 200 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0199', text: "He who thinks he has the power to content the world greatly deceives himself, but he who thinks that the world cannot be content with him deceives himself yet more.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 201 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0200', text: "Falsely honest men are those who disguise their faults both to themselves and others; truly honest men are those who know them perfectly and confess them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 202 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0201', text: "He is really wise who is nettled at nothing.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 203 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0202', text: "The coldness of women is a balance and burden they add to their beauty.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 204 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0203', text: "Virtue in woman is often the love of reputation and repose.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 205 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0204', text: "He is a truly good man who desires always to bear the inspection of good men.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 206 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0205', text: "Folly follows us at all stages of life. If one appears wise 'tis but because his folly is proportioned to his age and fortune.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 207 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0206', text: "There are foolish people who know and who skilfully use their folly.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 208 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0207', text: "Who lives without folly is not so wise as he thinks.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 209 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0208', text: "In growing old we become more foolish--and more wise.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 210 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0209', text: "There are people who are like farces, which are praised but for a time (however foolish and distasteful they may be).", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 211 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0210', text: "Most people judge men only by success or by fortune.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 212 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0211', text: "Love of glory, fear of shame, greed of fortune, the desire to make life agreeable and comfortable, and the wish to depreciate others are often causes of that bravery so vaunted among men.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 213 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0212', text: "Valour in common soldiers is a perilous method of earning their living.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 214 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0213', text: "Perfect valour is to do without witnesses what one would do before all the world.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 216 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0214', text: "Intrepidity is an extraordinary strength of soul which raises it above the troubles, disorders, and emotions which the sight of great perils can arouse in it: by this strength heroes maintain a calm aspect and preserve their reason and liberty in the most surprising and terrible accidents.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 217 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0215', text: "Hypocrisy is the homage vice pays to virtue.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 218 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0216', text: "Most men expose themselves in battle enough to save their honor, few wish to do so more than sufficiently, or than is necessary to make the design for which they expose themselves succeed.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 219 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0217', text: "Vanity, shame, and above all disposition, often make men brave and women chaste.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 220 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0218', text: "We do not wish to lose life; we do wish to gain glory, and this makes brave men show more tact and address in avoiding death, than rogues show in preserving their fortunes.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 221 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0219', text: "Few persons on the first approach of age do not show wherein their body, or their mind, is beginning to fail.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 222 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0220', text: "Gratitude is as the good faith of merchants: it holds commerce together; and we do not pay because it is just to pay debts, but because we shall thereby more easily find people who will lend.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 223 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0221', text: "All those who pay the debts of gratitude cannot thereby flatter themselves that they are grateful.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 224 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0222', text: "What makes false reckoning, as regards gratitude, is that the pride of the giver and the receiver cannot agree as to the value of the benefit.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 225 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0223', text: "Too great a hurry to discharge of an obligation is a kind of ingratitude.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 226 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0224', text: "Lucky people are bad hands at correcting their faults; they always believe that they are right when fortune backs up their vice or folly.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 227 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0225', text: "Pride will not owe, self-love will not pay.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 228 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0226', text: "The good we have received from a man should make us excuse the wrong he does us.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 229 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0227', text: "Nothing is so infectious as example, and we never do great good or evil without producing the like. We imitate good actions by emulation, and bad ones by the evil of our nature, which shame imprisons until example liberates.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 230 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0228', text: "It is great folly to wish only to be wise.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 231 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0229', text: "Whatever pretext we give to our afflictions it is always interest or vanity that causes them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 232 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0230', text: "It is more often from pride than from ignorance that we are so obstinately opposed to current opinions; we find the first places taken, and we do not want to be the last.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 234 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0231', text: "We are easily consoled at the misfortunes of our friends when they enable us to prove our tenderness for them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 235 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0232', text: "It would seem that even self-love may be the dupe of goodness and forget itself when we work for others. And yet it is but taking the shortest way to arrive at its aim, taking usury under the pretext of giving, in fact winning everybody in a subtle and delicate manner.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 236 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0233', text: "No one should be praised for his goodness if he has not strength enough to be wicked. All other goodness is but too often an idleness or powerlessness of will.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 237 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0234', text: "It is not so dangerous to do wrong to most men, as to do them too much good.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 238 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0235', text: "Nothing flatters our pride so much as the confidence of the great, because we regard it as the result of our worth, without remembering that generally 'tis but vanity, or the inability to keep a secret.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 239 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0236', text: "We may say of conformity as distinguished from beauty, that it is a symmetry which knows no rules, and a secret harmony of features both one with each other and with the colour and appearance of the person.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 240 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0237', text: "Flirtation is at the bottom of woman's nature, although all do not practise it, some being restrained by fear, others by sense.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 241 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0238', text: "We often bore others when we think we cannot possibly bore them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 242 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0239', text: "Few things are impossible in themselves; application to make them succeed fails us more often than the means.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 243 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0240', text: "Sovereign ability consists in knowing the value of things.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 244 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0241', text: "There is great ability in knowing how to conceal one's ability.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 245 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0242', text: "What seems generosity is often disguised ambition, that despises small to run after greater interest.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 246 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0243', text: "The fidelity of most men is merely an invention of self-love to win confidence; a method to place us above others and to render us depositaries of the most important matters.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 247 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0244', text: "Magnanimity despises all, to win all.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 248 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0245', text: "There is no less eloquence in the voice, in the eyes and in the air of a speaker than in his choice of words.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 249 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0246', text: "True eloquence consists in saying all that should be, not all that could be said.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 250 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0247', text: "There are people whose faults become them, others whose very virtues disgrace them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 251 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0248', text: "It is as common to change one's tastes, as it is uncommon to change one's inclinations.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 252 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0249', text: "Interest sets at work all sorts of virtues and vices.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 253 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0250', text: "All feelings have their peculiar tone of voice, gestures and looks, and this harmony, as it is good or bad, pleasant or unpleasant, makes people agreeable or disagreeable.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 255 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0251', text: "In all professions we affect a part and an appearance to seem what we wish to be. Thus the world is merely composed of actors.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 256 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0252', text: "Gravity is a mysterious carriage of the body invented to conceal the want of mind.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 257 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0253', text: "Good taste arises more from judgment than wit.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 258 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0254', text: "The pleasure of love is in loving, we are happier in the passion we feel than in that we inspire.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 259 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0255', text: "Civility is but a desire to receive civility, and to be esteemed polite.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 260 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0256', text: "The usual education of young people is to inspire them with a second self-love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 261 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0257', text: "There is no passion wherein self-love reigns so powerfully as in love, and one is always more ready to sacrifice the peace of the loved one than his own.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 262 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0258', text: "What we call liberality is often but the vanity of giving, which we like more than that we give away.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 263 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0259', text: "Pity is often a reflection of our own evils in the ills of others. It is a delicate foresight of the troubles into which we may fall. We help others that on like occasions we may be helped ourselves, and these services which we render, are in reality benefits we confer on ourselves by anticipation.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 264 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0260', text: "A narrow mind begets obstinacy, and we do not easily believe what we cannot see.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 265 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0261', text: "We deceive ourselves if we believe that there are violent passions like ambition and love that can triumph over others. Idleness, languishing as she is, does not often fail in being mistress; she usurps authority over all the plans and actions of life; imperceptibly consuming and destroying both passions and virtues.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 266 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0262', text: "A quickness in believing evil without having sufficiently examined it, is the effect of pride and laziness. We wish to find the guilty, and we do not wish to trouble ourselves in examining the crime.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 267 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0263', text: "We credit judges with the meanest motives, and yet we desire our reputation and fame should depend upon the judgment of men, who are all, either from their jealousy or pre-occupation or want of intelligence, opposed to us--and yet 'tis only to make these men decide in our favour that we peril in so many ways both our peace and our life.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 268 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0264', text: "No man is clever enough to know all the evil he does.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 269 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0265', text: "One honour won is a surety for more.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 270 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0266', text: "Youth is a continual intoxication; it is the fever of reason.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 271 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0267', text: "Nothing should so humiliate men who have deserved great praise, as the care they have taken to acquire it by the smallest means.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 272 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0268', text: "There are persons of whom the world approves who have no merit beyond the vices they use in the affairs of life.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 273 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0269', text: "The beauty of novelty is to love as the flower to the fruit; it lends a lustre which is easily lost, but which never returns.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 274 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0270', text: "Natural goodness, which boasts of being so apparent, is often smothered by the least interest.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 275 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0271', text: "Absence extinguishes small passions and increases great ones, as the wind will blow out a candle, and blow in a fire.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 276 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0272', text: "Women often think they love when they do not love. The business of a love affair, the emotion of mind that sentiment induces, the natural bias towards the pleasure of being loved, the difficulty of refusing, persuades them that they have real passion when they have but flirtation.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 277 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0273', text: "What makes us so often discontented with those who transact business for us is that they almost always abandon the interest of their friends for the interest of the business, because they wish to have the honour of succeeding in that which they have undertaken.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 278 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0274', text: "When we exaggerate the tenderness of our friends towards us, it is often less from gratitude than from a desire to exhibit our own merit.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 279 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0275', text: "The praise we give to new comers into the world arises from the envy we bear to those who are established.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 280 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0276', text: "Pride, which inspires, often serves to moderate envy.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 281 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0277', text: "Some disguised lies so resemble truth, that we should judge badly were we not deceived.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 282 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0278', text: "Sometimes there is not less ability in knowing how to use than in giving good advice.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 283 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0279', text: "There are wicked people who would be much less dangerous if they were wholly without goodness.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 284 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0280', text: "Magnanimity is sufficiently defined by its name, nevertheless one can say it is the good sense of pride, the most noble way of receiving praise.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 285 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0281', text: "It is impossible to love a second time those whom we have really ceased to love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 286 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0282', text: "Fertility of mind does not furnish us with so many resources on the same matter, as the lack of intelligence makes us hesitate at each thing our imagination presents, and hinders us from at first discerning which is the best.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 287 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0283', text: "There are matters and maladies which at certain times remedies only serve to make worse; true skill consists in knowing when it is dangerous to use them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 288 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0284', text: "Affected simplicity is refined imposture.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 289 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0285', text: "There are as many errors of temper as of mind.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 290 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0286', text: "Man's merit, like the crops, has its season.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 291 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0287', text: "One may say of temper as of many buildings; it has divers aspects, some agreeable, others disagreeable.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 292 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0288', text: "Moderation cannot claim the merit of opposing and overcoming Ambition: they are never found together. Moderation is the languor and sloth of the soul, Ambition its activity and heat.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 293 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0289', text: "We always like those who admire us, we do not always like those whom we admire.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 294 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0290', text: "It is well that we know not all our wishes.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 295 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0291', text: "It is difficult to love those we do not esteem, but it is no less so to love those whom we esteem much more than ourselves.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 296 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0292', text: "Bodily temperaments have a common course and rule which imperceptibly affect our will. They advance in combination, and successively exercise a secret empire over us, so that, without our perceiving it, they become a great part of all our actions.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 297 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0293', text: "The gratitude of most men is but a secret desire of receiving greater benefits.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 298 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0294', text: "Almost all the world takes pleasure in paying small debts; many people show gratitude for trifling, but there is hardly one who does not show ingratitude for great favours.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 299 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0295', text: "There are follies as catching as infections.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 300 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0296', text: "Many people despise, but few know how to bestow wealth.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 301 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0297', text: "Only in things of small value we usually are bold enough not to trust to appearances.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 302 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0298', text: "Whatever good quality may be imputed to us, we ourselves find nothing new in it.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 303 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0299', text: "We may forgive those who bore us, we cannot forgive those whom we bore.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 304 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0300', text: "Interest which is accused of all our misdeeds often should be praised for our good deeds.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 305 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0301', text: "We find very few ungrateful people when we are able to confer favours.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 306 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0302', text: "It is as proper to be boastful alone as it is ridiculous to be so in company.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 307 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0303', text: "Moderation is made a virtue to limit the ambition of the great; to console ordinary people for their small fortune and equally small ability.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 308 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0304', text: "There are persons fated to be fools, who commit follies not only by choice, but who are forced by fortune to do so.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 309 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0305', text: "Sometimes there are accidents in our life the skilful extrication from which demands a little folly.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 310 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0306', text: "If there be men whose folly has never appeared, it is because it has never been closely looked for.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 311 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0307', text: "Lovers are never tired of each other,--they always speak of themselves.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 312 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0308', text: "How is it that our memory is good enough to retain the least triviality that happens to us, and yet not good enough to recollect how often we have told it to the same person?", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 313 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0309', text: "The extreme delight we take in talking of ourselves should warn us that it is not shared by those who listen.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 314 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0310', text: "What commonly hinders us from showing the recesses of our heart to our friends, is not the distrust we have of them, but that we have of ourselves.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 315 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0311', text: "Weak persons cannot be sincere.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 316 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0312', text: "'Tis a small misfortune to oblige an ungrateful man; but it is unbearable to be obliged by a scoundrel.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 317 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0313', text: "We may find means to cure a fool of his folly, but there are none to set straight a cross-grained spirit.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 318 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0314', text: "If we take the liberty to dwell on their faults we cannot long preserve the feelings we should hold towards our friends and benefactors.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 319 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0315', text: "To praise princes for virtues they do not possess is but to reproach them with impunity.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 320 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0316', text: "We are nearer loving those who hate us, than those who love us more than we desire.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 321 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0317', text: "Those only are despicable who fear to be despised.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 322 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0318', text: "Our wisdom is no less at the mercy of Fortune than our goods.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 323 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0319', text: "There is more self-love than love in jealousy.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 324 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0320', text: "We often comfort ourselves by the weakness of evils, for which reason has not the strength to console us.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 325 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0321', text: "Ridicule dishonours more than dishonour itself.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 326 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0322', text: "We own to small faults to persuade others that we have not great ones.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 327 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0323', text: "Envy is more irreconcilable than hatred.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 328 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0324', text: "We believe, sometimes, that we hate flattery --we only dislike the method.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 329 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0325', text: "We pardon in the degree that we love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 330 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0326', text: "It is more difficult to be faithful to a mistress when one is happy, than when we are ill-treated by her.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 331 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0327', text: "Women do not know all their powers of flirtation.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 332 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0328', text: "Women cannot be completely severe unless they hate.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 333 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0329', text: "Women can less easily resign flirtations than love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 334 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0330', text: "In love deceit almost always goes further than mistrust.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 335 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0331', text: "There is a kind of love, the excess of which forbids jealousy.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 336 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0332', text: "There are certain good qualities as there are senses, and those who want them can neither perceive nor understand them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 337 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0333', text: "When our hatred is too bitter it places us below those whom we hate.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 338 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0334', text: "We only appreciate our good or evil in proportion to our self-love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 339 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0335', text: "The wit of most women rather strengthens their folly than their reason.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 340 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0336', text: "The heat of youth is not more opposed to safety than the coldness of age.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 341 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0337', text: "The accent of our native country dwells in the heart and mind as well as on the tongue.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 342 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0338', text: "To be a great man one should know how to profit by every phase of fortune.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 343 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0339', text: "Most men, like plants, possess hidden qualities which chance discovers.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 344 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0340', text: "Opportunity makes us known to others, but more to ourselves.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 345 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0341', text: "If a woman's temper is beyond control there can be no control of the mind or heart.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 346 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0342', text: "We hardly find any persons of good sense, save those who agree with us.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 347 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0343', text: "When one loves one doubts even what one most believes.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 348 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0344', text: "The greatest miracle of love is to eradicate flirtation.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 349 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0345', text: "Why we hate with so much bitterness those who deceive us is because they think themselves more clever than we are.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 350 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0346', text: "We have much trouble to break with one, when we no longer are in love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 351 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0347', text: "We almost always are bored with persons with whom we should not be bored.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 352 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0348', text: "A gentleman may love like a lunatic, but not like a beast.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 353 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0349', text: "There are certain defects which well mounted glitter like virtue itself.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 354 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0350', text: "Sometimes we lose friends for whose loss our regret is greater than our grief, and others for whom our grief is greater than our regret.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 355 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0351', text: "Usually we only praise heartily those who admire us.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 356 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0352', text: "Little minds are too much wounded by little things; great minds see all and are not even hurt.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 357 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0353', text: "Humility is the true proof of Christian virtues; without it we retain all our faults, and they are only covered by pride to hide them from others, and often from ourselves.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 358 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0354', text: "Infidelities should extinguish love, and we ought not to be jealous when we have cause to be so. No persons escape causing jealousy who are worthy of exciting it.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 359 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0355', text: "We are more humiliated by the least infidelity towards us, than by our greatest towards others.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 360 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0356', text: "Jealousy is always born with love, but does not always die with it.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 361 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0357', text: "Most women do not grieve so much for the death of their lovers for love's-sake, as to show they were worthy of being beloved.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 362 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0358', text: "The evils we do to others give us less pain than those we do to ourselves.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 363 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0359', text: "We well know that it is bad taste to talk of our wives; but we do not so well know that it is the same to speak of ourselves.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 364 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0360', text: "There are virtues which degenerate into vices when they arise from Nature, and others which when acquired are never perfect. For example, reason must teach us to manage our estate and our confidence, while Nature should have given us goodness and valour.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 365 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0361', text: "However we distrust the sincerity of those whom we talk with, we always believe them more sincere with us than with others.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 366 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0362', text: "There are few virtuous women who are not tired of their part.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 367 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0363', text: "The greater number of good women are like concealed treasures, safe as no one has searched for them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 368 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0364', text: "The violences we put upon ourselves to escape love are often more cruel than the cruelty of those we love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 369 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0365', text: "There are not many cowards who know the whole of their fear.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 370 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0366', text: "It is generally the fault of the loved one not to perceive when love ceases.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 371 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0367', text: "Most young people think they are natural when they are only boorish and rude.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 372 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0368', text: "Some tears after having deceived others deceive ourselves.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 373 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0369', text: "If we think we love a woman for love of herself we are greatly deceived.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 374 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0370', text: "Ordinary men commonly condemn what is beyond them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 375 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0371', text: "Envy is destroyed by true friendship, flirtation by true love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 376 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0372', text: "The greatest mistake of penetration is not to have fallen short, but to have gone too far.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 377 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0373', text: "We may bestow advice, but we cannot inspire the conduct.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 378 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0374', text: "As our merit declines so also does our taste.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 379 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0375', text: "Fortune makes visible our virtues or our vices, as light does objects.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 380 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0376', text: "The struggle we undergo to remain faithful to one we love is little better than infidelity.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 381 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0377', text: "Our actions are like the rhymed ends of blank verses (Bouts-Rimes) where to each one puts what construction he pleases.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 382 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0378', text: "The desire of talking about ourselves, and of putting our faults in the light we wish them to be seen, forms a great part of our sincerity.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 383 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0379', text: "We should only be astonished at still being able to be astonished.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 384 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0380', text: "It is equally as difficult to be contented when one has too much or too little love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 385 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0381', text: "No people are more often wrong than those who will not allow themselves to be wrong.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 386 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0382', text: "A fool has not stuff in him to be good.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 387 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0383', text: "If vanity does not overthrow all virtues, at least she makes them totter.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 388 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0384', text: "What makes the vanity of others unsupportable is that it wounds our own.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 389 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0385', text: "We give up more easily our interest than our taste.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 390 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0386', text: "Fortune appears so blind to none as to those to whom she has done no good.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 391 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0387', text: "We should manage fortune like our health, enjoy it when it is good, be patient when it is bad, and never resort to strong remedies but in an extremity.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 392 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0388', text: "Awkwardness sometimes disappears in the camp, never in the court.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 393 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0389', text: "A man is often more clever than one other, but not than all others.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 394 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0390', text: "We are often less unhappy at being deceived by one we loved, than on being deceived.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 395 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0391', text: "We keep our first lover for a long time--if we do not get a second.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 396 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0392', text: "We have not the courage to say generally that we have no faults, and that our enemies have no good qualities; but in fact we are not far from believing so.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 397 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0393', text: "Of all our faults that which we most readily admit is idleness: we believe that it makes all virtues ineffectual, and that without utterly destroying, it at least suspends their operation.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 398 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0394', text: "There is a kind of greatness which does not depend upon fortune: it is a certain manner what distinguishes us, and which seems to destine us for great things; it is the value we insensibly set upon ourselves; it is by this quality that we gain the deference of other men, and it is this which commonly raises us more above them, than birth, rank, or even merit itself.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 399 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0395', text: "There may be talent without position, but there is no position without some kind of talent.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 400 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0396', text: "Rank is to merit what dress is to a pretty woman.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 401 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0397', text: "What we find the least of in flirtation is love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 402 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0398', text: "Fortune sometimes uses our faults to exalt us, and there are tiresome people whose deserts would be ill rewarded if we did not desire to purchase their absence.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 403 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0399', text: "It appears that nature has hid at the bottom of our hearts talents and abilities unknown to us. It is only the passions that have the power of bringing them to light, and sometimes give us views more true and more perfect than art could possibly do.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 404 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0400', text: "We reach quite inexperienced the different stages of life, and often, in spite of the number of our years, we lack experience.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 405 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0401', text: "Flirts make it a point of honour to be jealous of their lovers, to conceal their envy of other women.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 406 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0402', text: "It may well be that those who have trapped us by their tricks do not seem to us so foolish as we seem to ourselves when trapped by the tricks of others.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 407 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0403', text: "The most dangerous folly of old persons who have been loveable is to forget that they are no longer so.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 408 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0404', text: "We should often be ashamed of our very best actions if the world only saw the motives which caused them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 409 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0405', text: "The greatest effort of friendship is not to show our faults to a friend, but to show him his own. 4ll.--We have few faults which are not far more excusable than the means we adopt to hide them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 410 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0406', text: "Whatever disgrace we may have deserved, it is almost always in our power to re-establish our character.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 412 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0407', text: "A man cannot please long who has only one kind of wit.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 413 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0408', text: "Idiots and lunatics see only their own wit.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 414 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0409', text: "Wit sometimes enables us to act rudely with impunity.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 415 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0410', text: "The vivacity which increases in old age is not far removed from folly.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 416 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0411', text: "In love the quickest is always the best cure.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 417 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0412', text: "Young women who do not want to appear flirts, and old men who do not want to appear ridiculous, should not talk of love as a matter wherein they can have any interest.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 418 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0413', text: "We may seem great in a post beneath our capacity, but we oftener seem little in a post above it.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 419 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0414', text: "We often believe we have constancy in misfortune when we have nothing but debasement, and we suffer misfortunes without regarding them as cowards who let themselves be killed from fear of defending themselves.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 420 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0415', text: "Conceit causes more conversation than wit.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 421 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0416', text: "All passions make us commit some faults, love alone makes us ridiculous.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 422 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0417', text: "Few know how to be old.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 423 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0418', text: "We often credit ourselves with vices the reverse of what we have, thus when weak we boast of our obstinacy.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 424 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0419', text: "Penetration has a spice of divination in it which tickles our vanity more than any other quality of the mind.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 425 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0420', text: "The charm of novelty and old custom, however opposite to each other, equally blind us to the faults of our friends.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 426 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0421', text: "Most friends sicken us of friendship, most devotees of devotion.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 427 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0422', text: "We easily forgive in our friends those faults we do not perceive.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 428 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0423', text: "Women who love, pardon more readily great indiscretions than little infidelities.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 429 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0424', text: "In the old age of love as in life we still survive for the evils, though no longer for the pleasures.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 430 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0425', text: "Nothing prevents our being unaffected so much as our desire to seem so.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 431 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0426', text: "To praise good actions heartily is in some measure to take part in them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 432 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0427', text: "The most certain sign of being born with great qualities is to be born without envy.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 433 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0428', text: "When our friends have deceived us we owe them but indifference to the tokens of their friendship, yet for their misfortunes we always owe them pity.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 434 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0429', text: "Luck and temper rule the world.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 435 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0430', text: "It is far easier to know men than to know man.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 436 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0431', text: "We should not judge of a man's merit by his great abilities, but by the use he makes of them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 437 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0432', text: "There is a certain lively gratitude which not only releases us from benefits received, but which also, by making a return to our friends as payment, renders them indebted to us.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 438 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0433', text: "We should earnestly desire but few things if we clearly knew what we desired.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 439 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0434', text: "The cause why the majority of women are so little given to friendship is, that it is insipid after having felt love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 440 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0435', text: "As in friendship so in love, we are often happier from ignorance than from knowledge.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 441 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0436', text: "We try to make a virtue of vices we are loth to correct.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 442 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0437', text: "The most violent passions give some respite, but vanity always disturbs us.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 443 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0438', text: "Old fools are more foolish than young fools.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 444 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0439', text: "Weakness is more hostile to virtue than vice.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 445 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0440', text: "What makes the grief of shame and jealousy so acute is that vanity cannot aid us in enduring them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 446 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0441', text: "Propriety is the least of all laws, but the most obeyed.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 447 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0442', text: "A well-trained mind has less difficulty in submitting to than in guiding an ill-trained mind.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 448 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0443', text: "When fortune surprises us by giving us some great office without having gradually led us to expect it, or without having raised our hopes, it is well nigh impossible to occupy it well, and to appear worthy to fill it.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 449 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0444', text: "Our pride is often increased by what we retrench from our other faults.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 450 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0445', text: "No fools so wearisome as those who have some wit.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 451 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0446', text: "No one believes that in every respect he is behind the man he considers the ablest in the world.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 452 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0447', text: "In great matters we should not try so much to create opportunities as to utilise those that offer themselves.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 453 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0448', text: "There are few occasions when we should make a bad bargain by giving up the good on condition that no ill was said of us.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 454 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0449', text: "However disposed the world may be to judge wrongly, it far oftener favours false merit than does justice to true.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 455 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0450', text: "Sometimes we meet a fool with wit, never one with discretion.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 456 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0451', text: "We should gain more by letting the world see what we are than by trying to seem what we are not.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 457 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0452', text: "Our enemies come nearer the truth in the opinions they form of us than we do in our opinion of ourselves.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 458 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0453', text: "There are many remedies to cure love, yet none are infallible.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 459 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0454', text: "It would be well for us if we knew all our passions make us do.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 460 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0455', text: "Age is a tyrant who forbids at the penalty of life all the pleasures of youth.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 461 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0456', text: "The same pride which makes us blame faults from which we believe ourselves free causes us to despise the good qualities we have not.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 462 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0457', text: "There is often more pride than goodness in our grief for our enemies' miseries; it is to show how superior we are to them, that we bestow on them the sign of our compassion.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 463 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0458', text: "There exists an excess of good and evil which surpasses our comprehension.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 464 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0459', text: "Innocence is most fortunate if it finds the same protection as crime.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 465 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0460', text: "Of all the violent passions the one that becomes a woman best is love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 466 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0461', text: "Vanity makes us sin more against our taste than reason.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 467 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0462', text: "Some bad qualities form great talents.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 468 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0463', text: "We never desire earnestly what we desire in reason.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 469 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0464', text: "All our qualities are uncertain and doubtful, both the good as well as the bad, and nearly all are creatures of opportunities.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 470 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0465', text: "In their first passion women love their lovers, in all the others they love love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 471 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0466', text: "Pride as the other passions has its follies. We are ashamed to own we are jealous, and yet we plume ourselves in having been and being able to be so.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 472 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0467', text: "However rare true love is, true friendship is rarer.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 473 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0468', text: "There are few women whose charm survives their beauty.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 474 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0469', text: "The desire to be pitied or to be admired often forms the greater part of our confidence.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 475 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0470', text: "Our envy always lasts longer than the happiness of those we envy.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 476 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0471', text: "The same firmness that enables us to resist love enables us to make our resistance durable and lasting. So weak persons who are always excited by passions are seldom really possessed of any.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 477 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0472', text: "Fancy does not enable us to invent so many different contradictions as there are by nature in every heart.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 478 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0473', text: "It is only people who possess firmness who can possess true gentleness. In those who appear gentle it is generally only weakness, which is readily converted into harshness.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 479 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0474', text: "Timidity is a fault which is dangerous to blame in those we desire to cure of it.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 480 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0475', text: "Nothing is rarer than true good nature, those who think they have it are generally only pliant or weak.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 481 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0476', text: "The mind attaches itself by idleness and habit to whatever is easy or pleasant. This habit always places bounds to our knowledge, and no one has ever yet taken the pains to enlarge and expand his mind to the full extent of its capacities.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 482 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0477', text: "Usually we are more satirical from vanity than malice.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 483 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0478', text: "When the heart is still disturbed by the relics of a passion it is proner to take up a new one than when wholly cured.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 484 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0479', text: "Those who have had great passions often find all their lives made miserable in being cured of them.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 485 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0480', text: "More persons exist without self-love than without envy.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 486 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0481', text: "We have more idleness in the mind than in the body.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 487 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0482', text: "The calm or disturbance of our mind does not depend so much on what we regard as the more important things of life, as in a judicious or injudicious arrangement of the little things of daily occurrence.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 488 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0483', text: "However wicked men may be, they do not dare openly to appear the enemies of virtue, and when they desire to persecute her they either pretend to believe her false or attribute crimes to her.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 489 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0484', text: "We often go from love to ambition, but we never return from ambition to love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 490 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0485', text: "Extreme avarice is nearly always mistaken, there is no passion which is oftener further away from its mark, nor upon which the present has so much power to the prejudice of the future.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 491 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0486', text: "Avarice often produces opposite results: there are an infinite number of persons who sacrifice their property to doubtful and distant expectations, others mistake great future advantages for small present interests.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 492 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0487', text: "It appears that men do not find they have enough faults, as they increase the number by certain peculiar qualities that they affect to assume, and which they cultivate with so great assiduity that at length they become natural faults, which they can no longer correct.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 493 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0488', text: "What makes us see that men know their faults better than we imagine, is that they are never wrong when they speak of their conduct; the same self-love that usually blinds them enlightens them, and gives them such true views as to make them suppress or disguise the smallest thing that might be censured.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 494 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0489', text: "Young men entering life should be either shy or bold; a solemn and sedate manner usually degenerates into impertinence.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 495 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0490', text: "Quarrels would not last long if the fault was only on one side.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 496 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0491', text: "It is valueless to a woman to be young unless pretty, or to be pretty unless young.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 497 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0492', text: "Some persons are so frivolous and fickle that they are as far removed from real defects as from substantial qualities.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 498 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0493', text: "We do not usually reckon a woman's first flirtation until she has had a second.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 499 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0494', text: "Some people are so self-occupied that when in love they find a mode by which to be engrossed with the passion without being so with the person they love.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 500 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0495', text: "Love, though so very agreeable, pleases more by its ways than by itself.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 501 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0496', text: "A little wit with good sense bores less in the long run than much wit with ill nature.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 502 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0497', text: "Jealousy is the worst of all evils, yet the one that is least pitied by those who cause it.", creator: "Francois duc de La Rochefoucauld", source: "Reflections; or, Sentences and Moral Maxims, Maxim 503 (1871 translation by J. W. Willis Bund and J. Hain Friswell)" },
  { id: 'starter-0498', text: "\"THE difference between you and myself,\" said a friend to me, \"is that you have said to all the masqueraders: 'I know you,' whilst I have left them the hope that they are deceiving me. That is why the world favours me more than you. It is a masked ball, the interest of which you have spoiled for others and the amusement for yourself.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0499', text: "A MAN of wit is lost, if to his wit he does not join energy of character. If you have the lantern of Diogenes, you must also have his cudgel.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0500', text: "THERE are more fools than wise men, and even in the wise man himself there is more folly than wisdom.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0501', text: "THE worst wasted of all days is that during which one has not laughed.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0502', text: "THE best philosophical attitude to adopt towards the world is a union of the sarcasm of gaiety with the indulgence of contempt.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0503', text: "WE must be just before being generous, as we must possess shirts before having lace embroideries.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0504', text: "EDUCATION must have two foundations--morality as a support for virtue, prudence as a defence for self against the vices of others. By letting the balance incline to the side of morality, you only make dupes or martyrs; by letting it incline to the other, you make calculating egoists. The one great social principle is to be just both to yourself and to others. If you must love your neighbour as yourself, it is at least as fair to love yourself as your neighbour.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0505', text: "PUBLIC opinion is a jurisdiction which the honest man must never fully recognize, and which he must never ignore.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0506', text: "IT must be admitted that to live in the world without from time to time acting a part is impossible. What distinguishes the honest man from the knave is, that the former only does so when absolutely obliged and to escape a danger, while the latter seeks for opportunities.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0507', text: "A MAN who is not only honest but wise owes it to himself to add to the prudence that satisfies his conscience, the prudence that foresees and disarms calumny.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0508', text: "I CANNOT conceive of a wisdom that lacks distrust: according to the Scriptures the beginning of wisdom is the fear of God--I believe it is rather the fear of men.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0509', text: "WE must needs have the power of uniting contrarieties: love of virtue with indifference to public opinion, taste for work with indifference to glory, attention to health with indifference to life.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0510', text: "THERE are few vices that prevent a man from having many friends so much as his too high qualities prevent him.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0511', text: "VANITY is often the motive that forces a man to summon up all the energy of his soul. Wood added to a steel point makes a dart, two feathers added to the wood make an arrow.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0512', text: "A MAN of no principles is also, as a rule, a man of no character, for had he been born with character, he would have felt the need of forming principles.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0513', text: "NEARLY all men are slaves for the same reason that the Spartans assigned for the servitude of the Persians--lack of power to pronounce the syllable, No. To be able to utter that word and live alone, are the only two means to preserve one's freedom and one's character.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0514', text: "WHAT I have learnt I no longer know; what I still know has come to me by intuition.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0515', text: "MAN can aspire to virtue; he cannot reasonably aim at finding truth.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0516', text: "MAN reaches each stage in his life as a novice.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0517', text: "THE majority of human beings in the world pass their lives in it so heedlessly and think so little, that they do not know that world which they have before their eyes every day. They do not, M. de B. wittily remarked, for the same reason that cockchafers have no acquaintance with natural history.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0518', text: "'TIS not generally known how much wit a man requires to avoid being ridiculous.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0519', text: "\"ARE you not ashamed to wish to speak better than you can?\" said Seneca to one of his sons who could not work out the exordium of an oration he was composing. One might say the same to those who adopt principles stronger than their character will bear. \"Are you not ashamed of wishing to be more of a philosopher than you can be?\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0520', text: "IN great actions men show themselves as they ought to be, in small actions as they are.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0521', text: "VAIN is equivalent to empty; thus vanity is so miserable a thing, that one cannot give it a worse name than its own. It proclaims itself for what it is.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0522', text: "CELEBRITY: the advantage of being known to those who do not know you.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0523', text: "THE love of glory a virtue! A strange virtue truly, that calls to its aid the co-operation of all the vices, that finds stimulants in ambition, envy, vanity, sometimes even avarice! Would Titus have been Titus had he had as his ministers Sejanus, Narcissus, and Tigellinus?", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0524', text: "IN order to forgive reason for the evil it has wrought on the majority of men, we must imagine for ourselves what man would be without his reason. 'Tis a necessary evil.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0525', text: "THOUGHT consoles us for all, and heals all. If at times it does you ill, ask it for the remedy for that ill and it will give it you.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0526', text: "THAT to feel makes one think is pretty generally admitted; that to think makes one feel finds less acceptance, but is almost as true.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0527', text: "THE intelligence is often to the heart what the library of a mansion is to the person of its master.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0528', text: "A BAD man will occasionally do a good action. One might say that he wishes to see whether it gives as much pleasure as honest folk assert.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0529', text: "STUPIDITY would not be absolute stupidity did it not fear intelligence. Vice would not be absolute vice did it not hate virtue.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0530', text: "ONE suspects the idleness of a knave and the silence of a fool.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0531', text: "GENEROSITY is the pitifulness of noble hearts.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0532', text: "ALL passions are exaggerated, otherwise they would not be passions.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0533', text: "\"THE manner in which I see you distributing praise and blame,\" said M. de B---- to a friend, \"would make the best man in the world anxious to be defamed.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0534', text: "FALSE modesty is the most decent of all deceptions.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0535', text: "THERE are certain failings that preserve one from some epidemic vices, just as it may be noted that in time of plague fever-stricken patients escape contagion.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0536', text: "THE philosopher who would fain extinguish his passions resembles the chemist who would like to let his furnace go out.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0537', text: "ONE of the great misfortunes of man is that even his good qualities are sometimes useless to him, and that the art of profiting by them and governing them wisely is often the tardy fruit of experience alone.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0538', text: "NATURE in causing reason and the passions to be born at one and the same time apparently wished by the latter gift to distract man from the evil she had done him by the former, and by only permitting him to live for a few years after the loss of his passions seems to show her pity by early deliverance from a life that reduces him to reason as his sole resource.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0539', text: "HOPE is but a charlatan that ceases not to deceive us. For myself happiness only began when I had lost it. I would fain inscribe upon the gate of Paradise the line that Dante wrote upon that of Hell--\"Lasciate ogni speranza, voi ch'entrate.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0540', text: "OUR reason sometimes makes us as unhappy as our passions, and in such a case one can say of a man that he is a patient poisoned by his physician.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0541', text: "IT is nature's will that wise men have their illusions as well as fools, to the end that they be not made too unhappy by their own wisdom.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0542', text: "THAT tree of the knowledge of good and evil in the Bible is a fine allegory. Is it not intended to signify that when one has penetrated to the depths of things, the consequent loss of illusions brings about the death of the soul--that is to say a complete detachment from all that moves and interests other men?", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0543', text: "THE physical world appears the work of a good and mighty Being who has had to abandon the execution of part of his plan to a maleficent Being. But the moral world seems rather the production of a crazy fiend's caprices.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0544', text: "WHEN I hear it argued that, taking everything into account, the least sensitive folk are the happiest, I remember the Indian proverb: \"Better to be seated than standing, better to be lying than seated, but better than all else to be dead.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0545', text: "LIVING is a disease from the pains of which sleep eases us every sixteen hours; sleep is but a palliative, death alone is the cure.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0546', text: "TIME diminishes for us the intensity of _absolute_ pleasures, to use the metaphysician's term, but apparently it increases _relative_ pleasures; and I suspect that this is the artifice by which nature is able to attach men to life after the loss of the objects or pleasures which most rendered it agreeable.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0547', text: "SOME ONE described Providence as the baptismal name of chance; no doubt some pious person will retort that chance is the nickname of Providence.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0548', text: "M. ---- said to me, _à propos_ of his constant offences against digestion, and of the pleasures in which he indulged--the only obstacles to his regaining his health: \"I should be marvellously well if it were not for myself.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0549', text: "NATURE seems to make use of men for the accomplishment of her designs without concerning herself about her instruments, like tyrants who rid themselves of those who have been of service to them.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0550', text: "THERE is no need to regard Burrhus as an absolutely virtuous man; he is only so, contrasted with Narcissus. Seneca and Burrhus are the honest men of an age in which there are none.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0551', text: "IN order to sum up in a single word the rarity of honest folk, a friend remarked to me that in society the honest man is a variety of the human species.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0552', text: "I USED to know a misanthrope who in his good-humoured moments would say: \"I should not be at all surprised if there were an honest man hidden away in some corner without any one knowing of him.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0553', text: "THE thrifty man is the richest, the miser the poorest of men.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0554', text: "AN empty headed fellow who has a passing flash of wit astonishes and scandalises one as does a cab horse at a gallop.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0555', text: "I SHOULD advise any one who wishes to obtain a favour of a minister to accost him with an air of melancholy rather than one of gaiety. We do not like to see others happier than ourselves.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0556', text: "HE that is precisely midway between our enemy and ourselves seems to us nearer our enemy; this is but an effect of optical laws, like that by which the jet of a fountain seems less distant from the other side of the basin than from that where we are standing.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0557', text: "IT was said of a man who was always conjuring up gloomy chimæras and saw only the dark side of everything: \"He builds dungeons in Spain.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0558', text: "MADAME DE ROCHEFORT was asked if she were anxious to know the future. \"No,\" she replied, \"it is too like the past.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0559', text: "THE new friends whom we make after attaining a certain age and by whom we would fain replace those whom we have lost, are to our old friends what glass eyes, false teeth and wooden legs are to real eyes, natural teeth and legs of flesh and bone.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0560', text: "BY learning the evil elements in nature we despise death, by learning those of society we despise life.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0561', text: "SOCIETY would be a charming affair if we were only interested in one another.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0562', text: "\"IN the world,\" remarked some one to me, \"you have three kinds of friends: the friends who love you, the friends who do not trouble their heads about you, and the friends who hate you.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0563', text: "IT must be admitted that in order to live happy in the world there are sides to the soul which we must absolutely paralyse.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0564', text: "MAN under present social conditions seems to me corrupted more by his reason than by his passions. His passions--I mean those that characterise the primitive man--have preserved for society the few natural elements it still possesses.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0565', text: "SPEAKING generally, were society not an artificial structure, every simple and genuine feeling would not produce the great effect it does; it would give pleasure without surprise, but, as a matter of fact, it both surprises and pleases. Our surprise is a satire on society, our pleasure an act of homage to nature.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0566', text: "OFTEN man lives by himself and he has need of virtue; he lives with others and he has need of honour.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0567', text: "THERE is a wide-spread belief that the art of pleasing is a valuable means of making one's fortune. But to know how to be bored is an art which gives far better results; indeed talent for making a fortune like that for succeeding with women, can almost be reduced to that art.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0568', text: "THE great always sell their society to the vanity of the little.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0569', text: "A PHILOSOPHER who had retired from the world wrote me a letter full of good advice and common sense. It concluded with these words: \"Farewell, my friend; maintain if you can the interests that bind you to society, but cultivate the feelings that cut you away from it.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0570', text: "SUCH is the miserable condition of men, that they must needs seek consolation in society for the evils of nature, and in nature for the evils of society. How many have failed to find either in one or the other distraction from their troubles!", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0571', text: "M. ---- WAS reproached for his love of solitude. \"You see,\" he said, \"I am more accustomed to my own failings than to those of other people.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0572', text: "WEAKNESS of character or lack of ideas, in a word all that can withhold us from living a solitary life, are things that preserve many a man from misanthropy.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0573', text: "\"WHY Madame de L. should be so anxious for me to visit her,\" said a friend to me, \"I do not know, for when some time has elapsed without my going I despise her less.\" The same might be said of the world in general.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0574', text: "I ASKED M. N---- why he had ceased to go into society. \"Because,\" he replied, \"I no longer love the women and I know the men.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0575', text: "WHAT makes the success of many books consists in the affinity there is between the mediocrity of the author's ideas and those of the public.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0576', text: "THE majority of the books of our time give one the impression of having been manufactured in a day out of books read the day before.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0577', text: "THERE are well-dressed foolish ideas just as there are well-dressed fools.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0578', text: "IT is when their age of passions is past that great men produce their masterpieces, just as it is after volcanic eruptions that the soil is most fertile.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0579', text: "THE tragic drama has the great moral drawback of attaching too high an importance to life and death.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0580', text: "SPERON-SPERONI admirably explains how it is that an author who, in his own opinion, delivers himself clearly, is sometimes obscure to his reader. \"It is because,\" he says, \"the author proceeds from the thought to the expression, the reader from the expression to the thought.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0581', text: "A MAN is not clever simply because he has many ideas, just as he is not necessarily a good general because he has many soldiers.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0582', text: "A POETASTER asked Chamfort's opinion on a couplet. \"Excellent,\" he said, \"were it not for its length.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0583', text: "SOME one has said that to plagiarise from the ancients is to play the pirate beyond the Equator, but that to steal from the moderns is to pick pockets at street corners.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0584', text: "AN interesting work might be compiled which would point out all the noxious ideas concerning the human spirit, society and morality, to be found argued or implicit in the most celebrated writings and the most highly revered authors; ideas which propagate religious superstition, evil political principles, despotism, class pride and popular prejudices of every kind. Such a work would demonstrate that nearly all books corrupt, and that the best do almost as much harm as good.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0585', text: "PHYSICAL scourges and the calamities of human nature rendered society necessary. Society has added to natural misfortunes. The drawbacks of society have made government necessary, and government adds to society's misfortunes. There is the history of human nature in a nutshell.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0586', text: "MEN'S ideas are like cards and other games. Ideas which I remember to have seen regarded as dangerous and over-bold have since become commonplace and almost trite, and have descended to men little worthy of them. So it is that some of the ideas which to-day we call audacious will be considered feeble and conventional by our descendants.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0587', text: "IT has been observed that writers on physics, natural history, physiology, and chemistry, are, as a rule, men of mild, equable temperament and happy; whilst, on the contrary, writers on politics, law, and even ethics, are of a sad and melancholy cast of mind. Nothing can be more simple: the former study nature, the latter society, the former contemplate the work of the supreme Being, the latter confine their gaze to the work of men. The respective results must needs be diverse.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0588', text: "SAID a witty misanthrope to me _à propos_ of the iniquities of men, \"It is only the uselessness of the first Deluge that preserves us from being visited by a second.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0589', text: "THERE are periods when public opinion is the worst of opinions.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0590', text: "THE majority of our social institutions seem to have as object the maintenance of man in a mediocrity of ideas and emotions, which renders him best fitted to govern or be governed.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0591', text: "THERE is no man who can be by himself alone so contemptible as a body of men, and there is no body of men that can be so contemptible as the public at large.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0592', text: "IT may be argued that every public idea, every accepted convention, is a piece of stupidity, for has it not commended itself to the greatest number?", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0593', text: "THE public is governed as it reasons. It is its right to say foolish things, as it is that of the ministers to do them.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0594', text: "A CERTAIN witty advocate remarked: \"One would risk being disgusted if one saw politics, justice, and one's dinner in the making.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0595', text: "'TIS easier to make certain things legal than to make them legitimate.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0596', text: "EXPERIENCE which enlightens private persons corrupts princes and officials.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0597', text: "WERE a historian like Tacitus to write a history of the best of our kings, giving an exact account of all the tyrannical acts and abuses of authority, the majority of which lie buried in the profoundest obscurity, there would be few reigns which would not inspire us with the same horror as that of Tiberius.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0598', text: "OFTEN in early youth an opinion or custom seems absurd to us, which, with advancing years, we discover has some justification and so appears less absurd. Ought we to conclude from this that certain customs are not so ridiculous as others? One might sometimes be tempted to think that they were established by people who had read the book of life through, and that they are judged by those who, despite their intelligence, have only glanced at a few pages.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0599', text: "LIKE animals that cannot breathe at a certain altitude without perishing, the slave dies in the atmosphere of freedom.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0600', text: "IT is unfortunate for men, fortunate perhaps for tyrants, that the poor and unhappy have not the instinct or pride of the elephant which does not reproduce itself in servitude.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0601', text: "THERE is no history worthy attention save that of free nations; the history of nations under the sway of despotism is no more than a collection of anecdotes.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0602', text: "WILL it be believed that despotism has its partizans on the ground of the necessity for encouraging the fine arts? The brilliancy of the reign of Louis XIV. has to an incredible extent multiplied the number of those who think thus. According to them the crowning glory of all human society is to have fine tragedies, fine comedies and other works of art. There are those who willingly forgive all the evil wrought by priests, since without the priests we should not have had the comedy of _Tartuffe_.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0603', text: "WHAT is a cardinal? He is a priest clad in scarlet, who receives a hundred thousand crowns from the king, to flout him in the name of the pope.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0604', text: "SOCIETY is composed of two great classes--those who have more dinners than appetite, and those who have more appetite than dinners.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0605', text: "CHANGE in fashion is the tax which the industry of the poor levies on the vanity of the rich.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0606', text: "IT is an incontestable fact that there are in France seven million folk who beg for alms, and another twelve millions who are too poor to give them.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0607', text: "THE nobility, say the nobles, is an intermediary between the king and the people.... Precisely; just as the hound is the intermediary between the huntsman and the hares.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0608', text: "FRANCE is a country where it is often useful to exhibit one's vices, and invariably dangerous to exhibit one's virtues.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0609', text: "A FRIEND said to me _à propos_ of some ridiculous ministerial blunders: \"If it were not for the government, we should have nothing left to laugh at in France.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0610', text: "IN France we leave unmolested those who set fire to the house and persecute those who sound the alarm bell.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0611', text: "PARIS is a city of gaieties and pleasures, where four fifths of the inhabitants die of grief.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0612', text: "WHEN princes condescend to emerge from their miserable systems of etiquette it is never in favour of a man of merit, but of a wench or a buffoon. When women forget themselves it is never for love of an honest man but of a rascal. In short when people break the yoke of public opinion, it is rarely to rise above it, nearly always to descend below it.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0613', text: "ONE must make choice between loving women and knowing them; there is no middle course.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0614', text: "NATURALISTS tell us that in all animal species degeneration begins in the female. In civilised society philosophers can apply this observation to morals.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0615', text: "APPARENTLY nature, in giving man an absolutely irradicable taste for women, must have foreseen that, without this precaution, the contempt inspired by the vices of their sex, vanity in particular, would be a great obstacle to the maintenance and propagation of the human species.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0616', text: "A MAN who professed to esteem women highly was asked if he had enjoyed the favours of many. \"Not so many as if I had despised them,\" he said.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0617', text: "WHATEVER evil a man may think of women, there is no woman but thinks more.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0618', text: "YOUNG women have a misfortune which they share with kings, that of having no friends; but happily they feel this misfortune as little as the kings: the latter's pomp and the former's vanity spare both that emotion.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0619', text: "MADAME DE MONTMORIN said to her son: \"You are going into society: I have only one piece of advice to give you, and that is to be in love with all the women.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0620', text: "A WITTY woman told me one day what may well be the secret of her sex: it is that every woman in choosing a lover takes more account of the way in which other women regard the man than of her own.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0621', text: "THE woman who esteems herself more for her gifts of soul or intelligence than for her beauty is above her sex. She who esteems herself more for her beauty than for her intelligence or soul is of her sex. But she who esteems herself more for her birth or rank than for her beauty is outside her sex, beneath it.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0622', text: "MADAME DE TALMONT, seeing M. de Richelieu neglecting her to pay attentions to Madame de Brionne, a very beautiful woman, but said to be rather stupid, remarked to him: \"You are not blind, Marshall, but I cannot help thinking you a little deaf.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0623', text: "MADEMOISELLE DUTHÉ having lost a lover, and the affair causing some talk, a man who called to see her found her playing the harp, and said with surprise: \"Good heavens! I was expecting to find you desolated with grief.\" \"Ah,\" she exclaimed in a pathetic tone, \"you ought to have seen me yesterday!\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0624', text: "A WOMAN was at a performance of the tragedy of _Mérope_, and did not weep: surprise was expressed. \"I could cry my eyes out,\" she said, \"but I have to go out to supper to-night.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0625', text: "A YOUNG man was advised to ask a woman of forty, with whom he had been head over ears in love, to return his letters. \"I don't suppose she has them any longer,\" he said. \"Oh yes,\" was the reply, \"about the age of thirty women begin to keep their love letters.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0626', text: "\"HE who has not seen much of _demi-mondaines_ does not understand women at all,\" gravely remarked to me a fond admirer of his own wife, who was unfaithful to him.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0627', text: "I REMEMBER to have seen a man forsaking the society of ballet girls because, so he said, he had found them as deceitful as honest women.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0628', text: "SOMEONE remarked of a lady who was not venal, followed her heart's promptings, and remained faithful to the object of her choice, \"She is a charming woman and lives as virtuously as is possible outside marriage and celibacy.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0629', text: "WOMEN only give to friendship what they borrow from love.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0630', text: "LOVE as it exists in society is nothing more than the exchange of two fancies and the contact of two epidermes.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0631', text: "DUCLOS was speaking one day of the paradise that everyone imagines for himself in his own way. \"Here are the ingredients for yours, Duclos,\" said Madame de Rochefort; \"Wine, bread, and cheese, and the first woman who might come on the scene.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0632', text: "APPARENTLY love does not seek real perfections--one might say it fears them. It only loves those which it creates or supposes, and so resembles those monarchs who only recognise the great things they themselves have achieved.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0633', text: "A MAN in love who pities the reasonable man seems to me like one who reads fairy tales and jeers at those who read history.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0634', text: "LOVE resembles epidemic diseases: the more one fears them, the more liable is one to infection.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0635', text: "IN witnessing or experiencing the pains inseparable from intense feeling in love and friendship, be it by the death of the loved person or by the accidents of life, one is tempted to believe that dissipation and frivolity are not such great follies after all, and that life is scarce worth more than what fashionable folk make of it.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0636', text: "MARRIAGE follows on love as smoke on flame.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0637', text: "LOVE gives greater pleasure than marriage for the same reason that romances are more amusing than history.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0638', text: "ONE of the best reasons you can have for never marrying is not so much that you are the woman's dupe as that she is not yours.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0639', text: "BOTH marriage and celibacy have their respective drawbacks: we shall be wise if we make choice of that which is not irremediable.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0640', text: "FOR thirty years a certain man went to spend every evening with Mme. ----. When his wife died his friends believed he would marry the other, and urged him to do so. \"No, no,\" he said, \"if I did, where should I have to spend my evenings?\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0641', text: "I WAS sitting at dinner beside a man who asked me if the lady opposite him was the wife of the gentleman at her side. I had noticed that the latter had not exchanged a word with his neighbour, so I replied: \"He either does not know her or else she _is_ his wife.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0642', text: "LORD BOLINGBROKE gave Louis XIV. a thousand proofs of affectionate attention during a very dangerous illness. The king with some astonishment remarked: \"I am the more touched by it because you English do not love kings.\" \"Sire,\" replied Bolingbroke, \"we are like those husbands who, having no love for their own wives, are only the more eager to please those of their neighbours.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0643', text: "TO turn a widow from the idea of marrying again, one of her friends remarked to her: \"Don't you see that it is a very fine thing to bear the name of a man who can no longer make a fool of himself?\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0644', text: "THE sincerest of affections lays the soul open to petty passions. Marriage makes your soul liable to your wife's petty passions; also, ambition, vanity, and the like.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0645', text: "LA GABRIELLI, a celebrated singer, having asked 5,000 ducats from the Empress of Russia as her fee for singing at St. Petersburg for two months, the latter replied: \"I pay none of my field marshals on that scale.\" \"In that case,\" said La Gabrielli, \"Your Majesty has only to make your field marshals sing.\" The Empress paid the 5,000 ducats without further demur.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0646', text: "A PRINT-SELLER asked, on June 25th, a high price for a portrait of Madame Lamotte, who had been flogged and branded on the 21st, giving as his reason that it was a proof before letters.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0647', text: "AN entertainment manager was asking M. de Villars to waive the right of free admission for the king's pages. \"You must observe, my lord,\" he said, \"that several pages make a volume.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0648', text: "MARSHALL DE BIRON had a very dangerous illness; he wished to confess himself, and said before several of his friends: \"What I owe to God, what I owe to the king, what I owe to the State--\" \"Hush, hush,\" interrupted one of his friends, \"you will die insolvent.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0649', text: "SOME young courtiers were supping with M. de Conflans. The first song of the evening was broad but not too improper. Immediately thereafter, however, M. de Fronsac rose and sang some abominable couplets which amazed the company, gay as it was. There was a dead silence, broken by M. de Conflans, who observed: \"Fronsac, you surprise me! There are ten bottles of champagne between that song and the first.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0650', text: "A WOMAN of ninety said to M. de Fontenelle, then ninety-five: \"Death has forgotten us.\" \"Hush!\" replied M. de Fontenelle, putting his finger to his lips.", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0651', text: "TO obtain dry weather, it was arranged to have a procession with the shrine of St. Geneviève. Scarcely had the cortege started, however, than it began to rain. On which the Bishop of Castres wittily remarked: \"The saint is mistaken--she believes we are asking her for rain.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0652', text: "I ONCE heard an orthodox person denouncing those who discuss articles of faith. \"Gentlemen,\" he said naïvely, \"a true Christian does not examine what he is ordered to believe. Dogma is like a bitter pill: if you chew it, you will never be able to swallow it.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0653', text: "M. DE ---- asked a certain bishop for a country house of his which he never occupied. \"Don't you know,\" said the bishop, \"that a man ought always to have some place to which he never goes, but where he believes he would be happy?\" \"Yes,\" replied M. de ----, \"it is quite true--that is what has made the fortune of Paradise.\"", creator: "Sebastien-Roch-Nicolas Chamfort", source: "The Cynic's Breviary: Maxims and Anecdotes (1902 translation by William G. Hutchison)" },
  { id: 'starter-0654', text: "The proverbs of Solomon the son of David, king of Israel;", creator: "Unknown", source: "The Proverbs, King James Version, 1:1" },
  { id: 'starter-0655', text: "To know wisdom and instruction; to perceive the words of understanding;", creator: "Unknown", source: "The Proverbs, King James Version, 1:2" },
  { id: 'starter-0656', text: "To receive the instruction of wisdom, justice, and judgment, and equity;", creator: "Unknown", source: "The Proverbs, King James Version, 1:3" },
  { id: 'starter-0657', text: "To give subtilty to the simple, to the young man knowledge and discretion.", creator: "Unknown", source: "The Proverbs, King James Version, 1:4" },
  { id: 'starter-0658', text: "A wise man will hear, and will increase learning; and a man of understanding shall attain unto wise counsels:", creator: "Unknown", source: "The Proverbs, King James Version, 1:5" },
  { id: 'starter-0659', text: "To understand a proverb, and the interpretation; the words of the wise, and their dark sayings.", creator: "Unknown", source: "The Proverbs, King James Version, 1:6" },
  { id: 'starter-0660', text: "The fear of the LORD is the beginning of knowledge: but fools despise wisdom and instruction.", creator: "Unknown", source: "The Proverbs, King James Version, 1:7" },
  { id: 'starter-0661', text: "My son, hear the instruction of thy father, and forsake not the law of thy mother:", creator: "Unknown", source: "The Proverbs, King James Version, 1:8" },
  { id: 'starter-0662', text: "For they shall be an ornament of grace unto thy head, and chains about thy neck.", creator: "Unknown", source: "The Proverbs, King James Version, 1:9" },
  { id: 'starter-0663', text: "Let us swallow them up alive as the grave; and whole, as those that go down into the pit:", creator: "Unknown", source: "The Proverbs, King James Version, 1:12" },
  { id: 'starter-0664', text: "We shall find all precious substance, we shall fill our houses with spoil:", creator: "Unknown", source: "The Proverbs, King James Version, 1:13" },
  { id: 'starter-0665', text: "Cast in thy lot among us; let us all have one purse:", creator: "Unknown", source: "The Proverbs, King James Version, 1:14" },
  { id: 'starter-0666', text: "My son, walk not thou in the way with them; refrain thy foot from their path:", creator: "Unknown", source: "The Proverbs, King James Version, 1:15" },
  { id: 'starter-0667', text: "Surely in vain the net is spread in the sight of any bird.", creator: "Unknown", source: "The Proverbs, King James Version, 1:17" },
  { id: 'starter-0668', text: "So are the ways of every one that is greedy of gain; which taketh away the life of the owners thereof.", creator: "Unknown", source: "The Proverbs, King James Version, 1:19" },
  { id: 'starter-0669', text: "Wisdom crieth without; she uttereth her voice in the streets:", creator: "Unknown", source: "The Proverbs, King James Version, 1:20" },
  { id: 'starter-0670', text: "She crieth in the chief place of concourse, in the openings of the gates: in the city she uttereth her words, saying,", creator: "Unknown", source: "The Proverbs, King James Version, 1:21" },
  { id: 'starter-0671', text: "How long, ye simple ones, will ye love simplicity? and the scorners delight in their scorning, and fools hate knowledge?", creator: "Unknown", source: "The Proverbs, King James Version, 1:22" },
  { id: 'starter-0672', text: "Turn you at my reproof: behold, I will pour out my spirit unto you, I will make known my words unto you.", creator: "Unknown", source: "The Proverbs, King James Version, 1:23" },
  { id: 'starter-0673', text: "Because I have called, and ye refused; I have stretched out my hand, and no man regarded;", creator: "Unknown", source: "The Proverbs, King James Version, 1:24" },
  { id: 'starter-0674', text: "But ye have set at nought all my counsel, and would none of my reproof:", creator: "Unknown", source: "The Proverbs, King James Version, 1:25" },
  { id: 'starter-0675', text: "I also will laugh at your calamity; I will mock when your fear cometh;", creator: "Unknown", source: "The Proverbs, King James Version, 1:26" },
  { id: 'starter-0676', text: "Then shall they call upon me, but I will not answer; they shall seek me early, but they shall not find me:", creator: "Unknown", source: "The Proverbs, King James Version, 1:28" },
  { id: 'starter-0677', text: "For that they hated knowledge, and did not choose the fear of the LORD:", creator: "Unknown", source: "The Proverbs, King James Version, 1:29" },
  { id: 'starter-0678', text: "They would none of my counsel: they despised all my reproof.", creator: "Unknown", source: "The Proverbs, King James Version, 1:30" },
  { id: 'starter-0679', text: "Therefore shall they eat of the fruit of their own way, and be filled with their own devices.", creator: "Unknown", source: "The Proverbs, King James Version, 1:31" },
  { id: 'starter-0680', text: "But whoso hearkeneth unto me shall dwell safely, and shall be quiet from fear of evil.", creator: "Unknown", source: "The Proverbs, King James Version, 1:33" },
  { id: 'starter-0681', text: "My son, if thou wilt receive my words, and hide my commandments with thee;", creator: "Unknown", source: "The Proverbs, King James Version, 2:1" },
  { id: 'starter-0682', text: "So that thou incline thine ear unto wisdom, and apply thine heart to understanding;", creator: "Unknown", source: "The Proverbs, King James Version, 2:2" },
  { id: 'starter-0683', text: "Yea, if thou criest after knowledge, and liftest up thy voice for understanding;", creator: "Unknown", source: "The Proverbs, King James Version, 2:3" },
  { id: 'starter-0684', text: "If thou seekest her as silver, and searchest for her as for hid treasures;", creator: "Unknown", source: "The Proverbs, King James Version, 2:4" },
  { id: 'starter-0685', text: "Then shalt thou understand the fear of the LORD, and find the knowledge of God.", creator: "Unknown", source: "The Proverbs, King James Version, 2:5" },
  { id: 'starter-0686', text: "For the LORD giveth wisdom: out of his mouth cometh knowledge and understanding.", creator: "Unknown", source: "The Proverbs, King James Version, 2:6" },
  { id: 'starter-0687', text: "He layeth up sound wisdom for the righteous: he is a buckler to them that walk uprightly.", creator: "Unknown", source: "The Proverbs, King James Version, 2:7" },
  { id: 'starter-0688', text: "He keepeth the paths of judgment, and preserveth the way of his saints.", creator: "Unknown", source: "The Proverbs, King James Version, 2:8" },
  { id: 'starter-0689', text: "Then shalt thou understand righteousness, and judgment, and equity; yea, every good path.", creator: "Unknown", source: "The Proverbs, King James Version, 2:9" },
  { id: 'starter-0690', text: "When wisdom entereth into thine heart, and knowledge is pleasant unto thy soul;", creator: "Unknown", source: "The Proverbs, King James Version, 2:10" },
  { id: 'starter-0691', text: "Discretion shall preserve thee, understanding shall keep thee:", creator: "Unknown", source: "The Proverbs, King James Version, 2:11" },
  { id: 'starter-0692', text: "To deliver thee from the way of the evil man, from the man that speaketh froward things;", creator: "Unknown", source: "The Proverbs, King James Version, 2:12" },
  { id: 'starter-0693', text: "Who leave the paths of uprightness, to walk in the ways of darkness;", creator: "Unknown", source: "The Proverbs, King James Version, 2:13" },
  { id: 'starter-0694', text: "Whose ways are crooked, and they froward in their paths:", creator: "Unknown", source: "The Proverbs, King James Version, 2:15" },
  { id: 'starter-0695', text: "Which forsaketh the guide of her youth, and forgetteth the covenant of her God.", creator: "Unknown", source: "The Proverbs, King James Version, 2:17" },
  { id: 'starter-0696', text: "For her house inclineth unto death, and her paths unto the dead.", creator: "Unknown", source: "The Proverbs, King James Version, 2:18" },
  { id: 'starter-0697', text: "None that go unto her return again, neither take they hold of the paths of life.", creator: "Unknown", source: "The Proverbs, King James Version, 2:19" },
  { id: 'starter-0698', text: "That thou mayest walk in the way of good men, and keep the paths of the righteous.", creator: "Unknown", source: "The Proverbs, King James Version, 2:20" },
  { id: 'starter-0699', text: "For the upright shall dwell in the land, and the perfect shall remain in it.", creator: "Unknown", source: "The Proverbs, King James Version, 2:21" },
  { id: 'starter-0700', text: "My son, forget not my law; but let thine heart keep my commandments:", creator: "Unknown", source: "The Proverbs, King James Version, 3:1" },
  { id: 'starter-0701', text: "For length of days, and long life, and peace, shall they add to thee.", creator: "Unknown", source: "The Proverbs, King James Version, 3:2" },
  { id: 'starter-0702', text: "Let not mercy and truth forsake thee: bind them about thy neck; write them upon the table of thine heart:", creator: "Unknown", source: "The Proverbs, King James Version, 3:3" },
  { id: 'starter-0703', text: "So shalt thou find favour and good understanding in the sight of God and man.", creator: "Unknown", source: "The Proverbs, King James Version, 3:4" },
  { id: 'starter-0704', text: "Trust in the LORD with all thine heart; and lean not unto thine own understanding.", creator: "Unknown", source: "The Proverbs, King James Version, 3:5" },
  { id: 'starter-0705', text: "In all thy ways acknowledge him, and he shall direct thy paths.", creator: "Unknown", source: "The Proverbs, King James Version, 3:6" },
  { id: 'starter-0706', text: "Be not wise in thine own eyes: fear the LORD, and depart from evil.", creator: "Unknown", source: "The Proverbs, King James Version, 3:7" },
  { id: 'starter-0707', text: "It shall be health to thy navel, and marrow to thy bones.", creator: "Unknown", source: "The Proverbs, King James Version, 3:8" },
  { id: 'starter-0708', text: "Honour the LORD with thy substance, and with the firstfruits of all thine increase:", creator: "Unknown", source: "The Proverbs, King James Version, 3:9" },
  { id: 'starter-0709', text: "So shall thy barns be filled with plenty, and thy presses shall burst out with new wine.", creator: "Unknown", source: "The Proverbs, King James Version, 3:10" },
  { id: 'starter-0710', text: "My son, despise not the chastening of the LORD; neither be weary of his correction:", creator: "Unknown", source: "The Proverbs, King James Version, 3:11" },
  { id: 'starter-0711', text: "For whom the LORD loveth he correcteth; even as a father the son in whom he delighteth.", creator: "Unknown", source: "The Proverbs, King James Version, 3:12" },
  { id: 'starter-0712', text: "Happy is the man that findeth wisdom, and the man that getteth understanding.", creator: "Unknown", source: "The Proverbs, King James Version, 3:13" },
  { id: 'starter-0713', text: "For the merchandise of it is better than the merchandise of silver, and the gain thereof than fine gold.", creator: "Unknown", source: "The Proverbs, King James Version, 3:14" },
  { id: 'starter-0714', text: "She is more precious than rubies: and all the things thou canst desire are not to be compared unto her.", creator: "Unknown", source: "The Proverbs, King James Version, 3:15" },
  { id: 'starter-0715', text: "Length of days is in her right hand; and in her left hand riches and honour.", creator: "Unknown", source: "The Proverbs, King James Version, 3:16" },
  { id: 'starter-0716', text: "Her ways are ways of pleasantness, and all her paths are peace.", creator: "Unknown", source: "The Proverbs, King James Version, 3:17" },
  { id: 'starter-0717', text: "She is a tree of life to them that lay hold upon her: and happy is every one that retaineth her.", creator: "Unknown", source: "The Proverbs, King James Version, 3:18" },
  { id: 'starter-0718', text: "The LORD by wisdom hath founded the earth; by understanding hath he established the heavens.", creator: "Unknown", source: "The Proverbs, King James Version, 3:19" },
  { id: 'starter-0719', text: "By his knowledge the depths are broken up, and the clouds drop down the dew.", creator: "Unknown", source: "The Proverbs, King James Version, 3:20" },
  { id: 'starter-0720', text: "My son, let not them depart from thine eyes: keep sound wisdom and discretion:", creator: "Unknown", source: "The Proverbs, King James Version, 3:21" },
  { id: 'starter-0721', text: "So shall they be life unto thy soul, and grace to thy neck.", creator: "Unknown", source: "The Proverbs, King James Version, 3:22" },
  { id: 'starter-0722', text: "Then shalt thou walk in thy way safely, and thy foot shall not stumble.", creator: "Unknown", source: "The Proverbs, King James Version, 3:23" },
  { id: 'starter-0723', text: "When thou liest down, thou shalt not be afraid: yea, thou shalt lie down, and thy sleep shall be sweet.", creator: "Unknown", source: "The Proverbs, King James Version, 3:24" },
  { id: 'starter-0724', text: "For the LORD shall be thy confidence, and shall keep thy foot from being taken.", creator: "Unknown", source: "The Proverbs, King James Version, 3:26" },
  { id: 'starter-0725', text: "Withhold not good from them to whom it is due, when it is in the power of thine hand to do it.", creator: "Unknown", source: "The Proverbs, King James Version, 3:27" },
  { id: 'starter-0726', text: "Say not unto thy neighbour, Go, and come again, and to morrow I will give; when thou hast it by thee.", creator: "Unknown", source: "The Proverbs, King James Version, 3:28" },
  { id: 'starter-0727', text: "Devise not evil against thy neighbour, seeing he dwelleth securely by thee.", creator: "Unknown", source: "The Proverbs, King James Version, 3:29" },
  { id: 'starter-0728', text: "Strive not with a man without cause, if he have done thee no harm.", creator: "Unknown", source: "The Proverbs, King James Version, 3:30" },
  { id: 'starter-0729', text: "Envy thou not the oppressor, and choose none of his ways.", creator: "Unknown", source: "The Proverbs, King James Version, 3:31" },
  { id: 'starter-0730', text: "For the froward is abomination to the LORD: but his secret is with the righteous.", creator: "Unknown", source: "The Proverbs, King James Version, 3:32" },
  { id: 'starter-0731', text: "Surely he scorneth the scorners: but he giveth grace unto the lowly.", creator: "Unknown", source: "The Proverbs, King James Version, 3:34" },
  { id: 'starter-0732', text: "The wise shall inherit glory: but shame shall be the promotion of fools.", creator: "Unknown", source: "The Proverbs, King James Version, 3:35" },
  { id: 'starter-0733', text: "Hear, ye children, the instruction of a father, and attend to know understanding.", creator: "Unknown", source: "The Proverbs, King James Version, 4:1" },
  { id: 'starter-0734', text: "For I give you good doctrine, forsake ye not my law.", creator: "Unknown", source: "The Proverbs, King James Version, 4:2" },
  { id: 'starter-0735', text: "For I was my father's son, tender and only beloved in the sight of my mother.", creator: "Unknown", source: "The Proverbs, King James Version, 4:3" },
  { id: 'starter-0736', text: "He taught me also, and said unto me, Let thine heart retain my words: keep my commandments, and live.", creator: "Unknown", source: "The Proverbs, King James Version, 4:4" },
  { id: 'starter-0737', text: "Get wisdom, get understanding: forget it not; neither decline from the words of my mouth.", creator: "Unknown", source: "The Proverbs, King James Version, 4:5" },
  { id: 'starter-0738', text: "Forsake her not, and she shall preserve thee: love her, and she shall keep thee.", creator: "Unknown", source: "The Proverbs, King James Version, 4:6" },
  { id: 'starter-0739', text: "Wisdom is the principal thing; therefore get wisdom: and with all thy getting get understanding.", creator: "Unknown", source: "The Proverbs, King James Version, 4:7" },
  { id: 'starter-0740', text: "Exalt her, and she shall promote thee: she shall bring thee to honour, when thou dost embrace her.", creator: "Unknown", source: "The Proverbs, King James Version, 4:8" },
  { id: 'starter-0741', text: "She shall give to thine head an ornament of grace: a crown of glory shall she deliver to thee.", creator: "Unknown", source: "The Proverbs, King James Version, 4:9" },
  { id: 'starter-0742', text: "Hear, O my son, and receive my sayings; and the years of thy life shall be many.", creator: "Unknown", source: "The Proverbs, King James Version, 4:10" },
  { id: 'starter-0743', text: "I have taught thee in the way of wisdom; I have led thee in right paths.", creator: "Unknown", source: "The Proverbs, King James Version, 4:11" },
  { id: 'starter-0744', text: "When thou goest, thy steps shall not be straitened; and when thou runnest, thou shalt not stumble.", creator: "Unknown", source: "The Proverbs, King James Version, 4:12" },
  { id: 'starter-0745', text: "Take fast hold of instruction; let her not go: keep her; for she is thy life.", creator: "Unknown", source: "The Proverbs, King James Version, 4:13" },
  { id: 'starter-0746', text: "Avoid it, pass not by it, turn from it, and pass away.", creator: "Unknown", source: "The Proverbs, King James Version, 4:15" },
  { id: 'starter-0747', text: "For they sleep not, except they have done mischief; and their sleep is taken away, unless they cause some to fall.", creator: "Unknown", source: "The Proverbs, King James Version, 4:16" },
  { id: 'starter-0748', text: "But the path of the just is as the shining light, that shineth more and more unto the perfect day.", creator: "Unknown", source: "The Proverbs, King James Version, 4:18" },
  { id: 'starter-0749', text: "My son, attend to my words; incline thine ear unto my sayings.", creator: "Unknown", source: "The Proverbs, King James Version, 4:20" },
  { id: 'starter-0750', text: "Let them not depart from thine eyes; keep them in the midst of thine heart.", creator: "Unknown", source: "The Proverbs, King James Version, 4:21" },
  { id: 'starter-0751', text: "For they are life unto those that find them, and health to all their flesh.", creator: "Unknown", source: "The Proverbs, King James Version, 4:22" },
  { id: 'starter-0752', text: "Keep thy heart with all diligence; for out of it are the issues of life.", creator: "Unknown", source: "The Proverbs, King James Version, 4:23" },
  { id: 'starter-0753', text: "Put away from thee a froward mouth, and perverse lips put far from thee.", creator: "Unknown", source: "The Proverbs, King James Version, 4:24" },
  { id: 'starter-0754', text: "Let thine eyes look right on, and let thine eyelids look straight before thee.", creator: "Unknown", source: "The Proverbs, King James Version, 4:25" },
  { id: 'starter-0755', text: "Ponder the path of thy feet, and let all thy ways be established.", creator: "Unknown", source: "The Proverbs, King James Version, 4:26" },
  { id: 'starter-0756', text: "Turn not to the right hand nor to the left: remove thy foot from evil.", creator: "Unknown", source: "The Proverbs, King James Version, 4:27" },
  { id: 'starter-0757', text: "My son, attend unto my wisdom, and bow thine ear to my understanding:", creator: "Unknown", source: "The Proverbs, King James Version, 5:1" },
  { id: 'starter-0758', text: "That thou mayest regard discretion, and that thy lips may keep knowledge.", creator: "Unknown", source: "The Proverbs, King James Version, 5:2" },
  { id: 'starter-0759', text: "But her end is bitter as wormwood, sharp as a two-edged sword.", creator: "Unknown", source: "The Proverbs, King James Version, 5:4" },
  { id: 'starter-0760', text: "Her feet go down to death; her steps take hold on hell.", creator: "Unknown", source: "The Proverbs, King James Version, 5:5" },
  { id: 'starter-0761', text: "Lest thou shouldest ponder the path of life, her ways are moveable, that thou canst not know them.", creator: "Unknown", source: "The Proverbs, King James Version, 5:6" },
  { id: 'starter-0762', text: "Hear me now therefore, O ye children, and depart not from the words of my mouth.", creator: "Unknown", source: "The Proverbs, King James Version, 5:7" },
  { id: 'starter-0763', text: "Remove thy way far from her, and come not nigh the door of her house:", creator: "Unknown", source: "The Proverbs, King James Version, 5:8" },
  { id: 'starter-0764', text: "Lest thou give thine honour unto others, and thy years unto the cruel:", creator: "Unknown", source: "The Proverbs, King James Version, 5:9" },
  { id: 'starter-0765', text: "Lest strangers be filled with thy wealth; and thy labours be in the house of a stranger;", creator: "Unknown", source: "The Proverbs, King James Version, 5:10" },
  { id: 'starter-0766', text: "And thou mourn at the last, when thy flesh and thy body are consumed,", creator: "Unknown", source: "The Proverbs, King James Version, 5:11" },
  { id: 'starter-0767', text: "And say, How have I hated instruction, and my heart despised reproof;", creator: "Unknown", source: "The Proverbs, King James Version, 5:12" },
  { id: 'starter-0768', text: "And have not obeyed the voice of my teachers, nor inclined mine ear to them that instructed me!", creator: "Unknown", source: "The Proverbs, King James Version, 5:13" },
  { id: 'starter-0769', text: "I was almost in all evil in the midst of the congregation and assembly.", creator: "Unknown", source: "The Proverbs, King James Version, 5:14" },
  { id: 'starter-0770', text: "Drink waters out of thine own cistern, and running waters out of thine own well.", creator: "Unknown", source: "The Proverbs, King James Version, 5:15" },
  { id: 'starter-0771', text: "Let thy fountains be dispersed abroad, and rivers of waters in the streets.", creator: "Unknown", source: "The Proverbs, King James Version, 5:16" },
  { id: 'starter-0772', text: "Let them be only thine own, and not strangers' with thee.", creator: "Unknown", source: "The Proverbs, King James Version, 5:17" },
  { id: 'starter-0773', text: "Let thy fountain be blessed: and rejoice with the wife of thy youth.", creator: "Unknown", source: "The Proverbs, King James Version, 5:18" },
  { id: 'starter-0774', text: "Let her be as the loving hind and pleasant roe; let her breasts satisfy thee at all times; and be thou ravished always with her love.", creator: "Unknown", source: "The Proverbs, King James Version, 5:19" },
  { id: 'starter-0775', text: "For the ways of man are before the eyes of the LORD, and he pondereth all his goings.", creator: "Unknown", source: "The Proverbs, King James Version, 5:21" },
  { id: 'starter-0776', text: "He shall die without instruction; and in the greatness of his folly he shall go astray.", creator: "Unknown", source: "The Proverbs, King James Version, 5:23" },
  { id: 'starter-0777', text: "My son, if thou be surety for thy friend, if thou hast stricken thy hand with a stranger,", creator: "Unknown", source: "The Proverbs, King James Version, 6:1" },
  { id: 'starter-0778', text: "Thou art snared with the words of thy mouth, thou art taken with the words of thy mouth.", creator: "Unknown", source: "The Proverbs, King James Version, 6:2" },
  { id: 'starter-0779', text: "Do this now, my son, and deliver thyself, when thou art come into the hand of thy friend; go, humble thyself, and make sure thy friend.", creator: "Unknown", source: "The Proverbs, King James Version, 6:3" },
  { id: 'starter-0780', text: "Give not sleep to thine eyes, nor slumber to thine eyelids.", creator: "Unknown", source: "The Proverbs, King James Version, 6:4" },
  { id: 'starter-0781', text: "Deliver thyself as a roe from the hand of the hunter, and as a bird from the hand of the fowler.", creator: "Unknown", source: "The Proverbs, King James Version, 6:5" },
  { id: 'starter-0782', text: "Go to the ant, thou sluggard; consider her ways, and be wise:", creator: "Unknown", source: "The Proverbs, King James Version, 6:6" },
  { id: 'starter-0783', text: "Which having no guide, overseer, or ruler,", creator: "Unknown", source: "The Proverbs, King James Version, 6:7" },
  { id: 'starter-0784', text: "Provideth her meat in the summer, and gathereth her food in the harvest.", creator: "Unknown", source: "The Proverbs, King James Version, 6:8" },
  { id: 'starter-0785', text: "How long wilt thou sleep, O sluggard? when wilt thou arise out of thy sleep?", creator: "Unknown", source: "The Proverbs, King James Version, 6:9" },
  { id: 'starter-0786', text: "Yet a little sleep, a little slumber, a little folding of the hands to sleep:", creator: "Unknown", source: "The Proverbs, King James Version, 24:33" },
  { id: 'starter-0787', text: "So shall thy poverty come as one that travelleth; and thy want as an armed man.", creator: "Unknown", source: "The Proverbs, King James Version, 24:34" },
  { id: 'starter-0788', text: "He winketh with his eyes, he speaketh with his feet, he teacheth with his fingers;", creator: "Unknown", source: "The Proverbs, King James Version, 6:13" },
  { id: 'starter-0789', text: "Frowardness is in his heart, he deviseth mischief continually; he soweth discord.", creator: "Unknown", source: "The Proverbs, King James Version, 6:14" },
  { id: 'starter-0790', text: "Therefore shall his calamity come suddenly; suddenly shall he be broken without remedy.", creator: "Unknown", source: "The Proverbs, King James Version, 6:15" },
  { id: 'starter-0791', text: "These six things doth the LORD hate: yea, seven are an abomination unto him:", creator: "Unknown", source: "The Proverbs, King James Version, 6:16" },
  { id: 'starter-0792', text: "A false witness that speaketh lies, and he that soweth discord among brethren.", creator: "Unknown", source: "The Proverbs, King James Version, 6:19" },
  { id: 'starter-0793', text: "My son, keep thy father's commandment, and forsake not the law of thy mother:", creator: "Unknown", source: "The Proverbs, King James Version, 6:20" },
  { id: 'starter-0794', text: "Bind them continually upon thine heart, and tie them about thy neck.", creator: "Unknown", source: "The Proverbs, King James Version, 6:21" },
  { id: 'starter-0795', text: "When thou goest, it shall lead thee; when thou sleepest, it shall keep thee; and when thou awakest, it shall talk with thee.", creator: "Unknown", source: "The Proverbs, King James Version, 6:22" },
  { id: 'starter-0796', text: "For the commandment is a lamp; and the law is light; and reproofs of instruction are the way of life:", creator: "Unknown", source: "The Proverbs, King James Version, 6:23" },
  { id: 'starter-0797', text: "Lust not after her beauty in thine heart; neither let her take thee with her eyelids.", creator: "Unknown", source: "The Proverbs, King James Version, 6:25" },
  { id: 'starter-0798', text: "For by means of a whorish woman a man is brought to a piece of bread: and the adultress will hunt for the precious life.", creator: "Unknown", source: "The Proverbs, King James Version, 6:26" },
  { id: 'starter-0799', text: "Can a man take fire in his bosom, and his clothes not be burned?", creator: "Unknown", source: "The Proverbs, King James Version, 6:27" },
  { id: 'starter-0800', text: "Can one go upon hot coals, and his feet not be burned?", creator: "Unknown", source: "The Proverbs, King James Version, 6:28" },
  { id: 'starter-0801', text: "So he that goeth in to his neighbour's wife; whosoever toucheth her shall not be innocent.", creator: "Unknown", source: "The Proverbs, King James Version, 6:29" },
  { id: 'starter-0802', text: "Men do not despise a thief, if he steal to satisfy his soul when he is hungry;", creator: "Unknown", source: "The Proverbs, King James Version, 6:30" },
  { id: 'starter-0803', text: "But if he be found, he shall restore sevenfold; he shall give all the substance of his house.", creator: "Unknown", source: "The Proverbs, King James Version, 6:31" },
  { id: 'starter-0804', text: "But whoso committeth adultery with a woman lacketh understanding: he that doeth it destroyeth his own soul.", creator: "Unknown", source: "The Proverbs, King James Version, 6:32" },
  { id: 'starter-0805', text: "A wound and dishonour shall he get; and his reproach shall not be wiped away.", creator: "Unknown", source: "The Proverbs, King James Version, 6:33" },
  { id: 'starter-0806', text: "For jealousy is the rage of a man: therefore he will not spare in the day of vengeance.", creator: "Unknown", source: "The Proverbs, King James Version, 6:34" },
  { id: 'starter-0807', text: "He will not regard any ransom; neither will he rest content, though thou givest many gifts.", creator: "Unknown", source: "The Proverbs, King James Version, 6:35" },
  { id: 'starter-0808', text: "My son, keep my words, and lay up my commandments with thee.", creator: "Unknown", source: "The Proverbs, King James Version, 7:1" },
  { id: 'starter-0809', text: "Keep my commandments, and live; and my law as the apple of thine eye.", creator: "Unknown", source: "The Proverbs, King James Version, 7:2" },
  { id: 'starter-0810', text: "Bind them upon thy fingers, write them upon the table of thine heart.", creator: "Unknown", source: "The Proverbs, King James Version, 7:3" },
  { id: 'starter-0811', text: "Say unto wisdom, Thou art my sister; and call understanding thy kinswoman:", creator: "Unknown", source: "The Proverbs, King James Version, 7:4" },
  { id: 'starter-0812', text: "For at the window of my house I looked through my casement,", creator: "Unknown", source: "The Proverbs, King James Version, 7:6" },
  { id: 'starter-0813', text: "And beheld among the simple ones, I discerned among the youths, a young man void of understanding,", creator: "Unknown", source: "The Proverbs, King James Version, 7:7" },
  { id: 'starter-0814', text: "Passing through the street near her corner; and he went the way to her house,", creator: "Unknown", source: "The Proverbs, King James Version, 7:8" },
  { id: 'starter-0815', text: "In the twilight, in the evening, in the black and dark night:", creator: "Unknown", source: "The Proverbs, King James Version, 7:9" },
  { id: 'starter-0816', text: "And, behold, there met him a woman with the attire of an harlot, and subtil of heart.", creator: "Unknown", source: "The Proverbs, King James Version, 7:10" },
  { id: 'starter-0817', text: "(She is loud and stubborn; her feet abide not in her house:", creator: "Unknown", source: "The Proverbs, King James Version, 7:11" },
  { id: 'starter-0818', text: "Now is she without, now in the streets, and lieth in wait at every corner.)", creator: "Unknown", source: "The Proverbs, King James Version, 7:12" },
  { id: 'starter-0819', text: "So she caught him, and kissed him, and with an impudent face said unto him,", creator: "Unknown", source: "The Proverbs, King James Version, 7:13" },
  { id: 'starter-0820', text: "I have peace offerings with me; this day have I payed my vows.", creator: "Unknown", source: "The Proverbs, King James Version, 7:14" },
  { id: 'starter-0821', text: "Therefore came I forth to meet thee, diligently to seek thy face, and I have found thee.", creator: "Unknown", source: "The Proverbs, King James Version, 7:15" },
  { id: 'starter-0822', text: "I have decked my bed with coverings of tapestry, with carved works, with fine linen of Egypt.", creator: "Unknown", source: "The Proverbs, King James Version, 7:16" },
  { id: 'starter-0823', text: "I have perfumed my bed with myrrh, aloes, and cinnamon.", creator: "Unknown", source: "The Proverbs, King James Version, 7:17" },
  { id: 'starter-0824', text: "Come, let us take our fill of love until the morning: let us solace ourselves with loves.", creator: "Unknown", source: "The Proverbs, King James Version, 7:18" },
  { id: 'starter-0825', text: "For the goodman is not at home, he is gone a long journey:", creator: "Unknown", source: "The Proverbs, King James Version, 7:19" },
  { id: 'starter-0826', text: "He hath taken a bag of money with him, and will come home at the day appointed.", creator: "Unknown", source: "The Proverbs, King James Version, 7:20" },
  { id: 'starter-0827', text: "With her much fair speech she caused him to yield, with the flattering of her lips she forced him.", creator: "Unknown", source: "The Proverbs, King James Version, 7:21" },
  { id: 'starter-0828', text: "Till a dart strike through his liver; as a bird hasteth to the snare, and knoweth not that it is for his life.", creator: "Unknown", source: "The Proverbs, King James Version, 7:23" },
  { id: 'starter-0829', text: "Hearken unto me now therefore, O ye children, and attend to the words of my mouth.", creator: "Unknown", source: "The Proverbs, King James Version, 7:24" },
  { id: 'starter-0830', text: "Let not thine heart decline to her ways, go not astray in her paths.", creator: "Unknown", source: "The Proverbs, King James Version, 7:25" },
  { id: 'starter-0831', text: "For she hath cast down many wounded: yea, many strong men have been slain by her.", creator: "Unknown", source: "The Proverbs, King James Version, 7:26" },
  { id: 'starter-0832', text: "Her house is the way to hell, going down to the chambers of death.", creator: "Unknown", source: "The Proverbs, King James Version, 7:27" },
  { id: 'starter-0833', text: "Doth not wisdom cry? and understanding put forth her voice?", creator: "Unknown", source: "The Proverbs, King James Version, 8:1" },
  { id: 'starter-0834', text: "She standeth in the top of high places, by the way in the places of the paths.", creator: "Unknown", source: "The Proverbs, King James Version, 8:2" },
  { id: 'starter-0835', text: "She crieth at the gates, at the entry of the city, at the coming in at the doors.", creator: "Unknown", source: "The Proverbs, King James Version, 8:3" },
  { id: 'starter-0836', text: "Unto you, O men, I call; and my voice is to the sons of man.", creator: "Unknown", source: "The Proverbs, King James Version, 8:4" },
  { id: 'starter-0837', text: "O ye simple, understand wisdom: and, ye fools, be ye of an understanding heart.", creator: "Unknown", source: "The Proverbs, King James Version, 8:5" },
  { id: 'starter-0838', text: "Hear; for I will speak of excellent things; and the opening of my lips shall be right things.", creator: "Unknown", source: "The Proverbs, King James Version, 8:6" },
  { id: 'starter-0839', text: "All the words of my mouth are in righteousness; there is nothing froward or perverse in them.", creator: "Unknown", source: "The Proverbs, King James Version, 8:8" },
  { id: 'starter-0840', text: "They are all plain to him that understandeth, and right to them that find knowledge.", creator: "Unknown", source: "The Proverbs, King James Version, 8:9" },
  { id: 'starter-0841', text: "Receive my instruction, and not silver; and knowledge rather than choice gold.", creator: "Unknown", source: "The Proverbs, King James Version, 8:10" },
  { id: 'starter-0842', text: "For wisdom is better than rubies; and all the things that may be desired are not to be compared to it.", creator: "Unknown", source: "The Proverbs, King James Version, 8:11" },
  { id: 'starter-0843', text: "I wisdom dwell with prudence, and find out knowledge of witty inventions.", creator: "Unknown", source: "The Proverbs, King James Version, 8:12" },
  { id: 'starter-0844', text: "The fear of the LORD is to hate evil: pride, and arrogancy, and the evil way, and the froward mouth, do I hate.", creator: "Unknown", source: "The Proverbs, King James Version, 8:13" },
  { id: 'starter-0845', text: "Counsel is mine, and sound wisdom: I am understanding; I have strength.", creator: "Unknown", source: "The Proverbs, King James Version, 8:14" },
  { id: 'starter-0846', text: "By me kings reign, and princes decree justice.", creator: "Unknown", source: "The Proverbs, King James Version, 8:15" },
  { id: 'starter-0847', text: "By me princes rule, and nobles, even all the judges of the earth.", creator: "Unknown", source: "The Proverbs, King James Version, 8:16" },
  { id: 'starter-0848', text: "I love them that love me; and those that seek me early shall find me.", creator: "Unknown", source: "The Proverbs, King James Version, 8:17" },
  { id: 'starter-0849', text: "Riches and honour are with me; yea, durable riches and righteousness.", creator: "Unknown", source: "The Proverbs, King James Version, 8:18" },
  { id: 'starter-0850', text: "My fruit is better than gold, yea, than fine gold; and my revenue than choice silver.", creator: "Unknown", source: "The Proverbs, King James Version, 8:19" },
  { id: 'starter-0851', text: "I lead in the way of righteousness, in the midst of the paths of judgment:", creator: "Unknown", source: "The Proverbs, King James Version, 8:20" },
  { id: 'starter-0852', text: "That I may cause those that love me to inherit substance; and I will fill their treasures.", creator: "Unknown", source: "The Proverbs, King James Version, 8:21" },
  { id: 'starter-0853', text: "The LORD possessed me in the beginning of his way, before his works of old.", creator: "Unknown", source: "The Proverbs, King James Version, 8:22" },
  { id: 'starter-0854', text: "I was set up from everlasting, from the beginning, or ever the earth was.", creator: "Unknown", source: "The Proverbs, King James Version, 8:23" },
  { id: 'starter-0855', text: "When there were no depths, I was brought forth; when there were no fountains abounding with water.", creator: "Unknown", source: "The Proverbs, King James Version, 8:24" },
  { id: 'starter-0856', text: "Before the mountains were settled, before the hills was I brought forth:", creator: "Unknown", source: "The Proverbs, King James Version, 8:25" },
  { id: 'starter-0857', text: "While as yet he had not made the earth, nor the fields, nor the highest part of the dust of the world.", creator: "Unknown", source: "The Proverbs, King James Version, 8:26" },
  { id: 'starter-0858', text: "When he prepared the heavens, I was there: when he set a compass upon the face of the depth:", creator: "Unknown", source: "The Proverbs, King James Version, 8:27" },
  { id: 'starter-0859', text: "When he established the clouds above: when he strengthened the fountains of the deep:", creator: "Unknown", source: "The Proverbs, King James Version, 8:28" },
  { id: 'starter-0860', text: "When he gave to the sea his decree, that the waters should not pass his commandment: when he appointed the foundations of the earth:", creator: "Unknown", source: "The Proverbs, King James Version, 8:29" },
  { id: 'starter-0861', text: "Then I was by him, as one brought up with him: and I was daily his delight, rejoicing always before him;", creator: "Unknown", source: "The Proverbs, King James Version, 8:30" },
  { id: 'starter-0862', text: "Rejoicing in the habitable part of his earth; and my delights were with the sons of men.", creator: "Unknown", source: "The Proverbs, King James Version, 8:31" },
  { id: 'starter-0863', text: "Now therefore hearken unto me, O ye children: for blessed are they that keep my ways.", creator: "Unknown", source: "The Proverbs, King James Version, 8:32" },
  { id: 'starter-0864', text: "Hear instruction, and be wise, and refuse it not.", creator: "Unknown", source: "The Proverbs, King James Version, 8:33" },
  { id: 'starter-0865', text: "Blessed is the man that heareth me, watching daily at my gates, waiting at the posts of my doors.", creator: "Unknown", source: "The Proverbs, King James Version, 8:34" },
  { id: 'starter-0866', text: "For whoso findeth me findeth life, and shall obtain favour of the LORD.", creator: "Unknown", source: "The Proverbs, King James Version, 8:35" },
  { id: 'starter-0867', text: "But he that sinneth against me wrongeth his own soul: all they that hate me love death.", creator: "Unknown", source: "The Proverbs, King James Version, 8:36" },
  { id: 'starter-0868', text: "Wisdom hath builded her house, she hath hewn out her seven pillars:", creator: "Unknown", source: "The Proverbs, King James Version, 9:1" },
  { id: 'starter-0869', text: "She hath killed her beasts; she hath mingled her wine; she hath also furnished her table.", creator: "Unknown", source: "The Proverbs, King James Version, 9:2" },
  { id: 'starter-0870', text: "She hath sent forth her maidens: she crieth upon the highest places of the city,", creator: "Unknown", source: "The Proverbs, King James Version, 9:3" },
  { id: 'starter-0871', text: "Whoso is simple, let him turn in hither: as for him that wanteth understanding, she saith to him,", creator: "Unknown", source: "The Proverbs, King James Version, 9:4" },
  { id: 'starter-0872', text: "Come, eat of my bread, and drink of the wine which I have mingled.", creator: "Unknown", source: "The Proverbs, King James Version, 9:5" },
  { id: 'starter-0873', text: "Forsake the foolish, and live; and go in the way of understanding.", creator: "Unknown", source: "The Proverbs, King James Version, 9:6" },
  { id: 'starter-0874', text: "Reprove not a scorner, lest he hate thee: rebuke a wise man, and he will love thee.", creator: "Unknown", source: "The Proverbs, King James Version, 9:8" },
  { id: 'starter-0875', text: "Give instruction to a wise man, and he will be yet wiser: teach a just man, and he will increase in learning.", creator: "Unknown", source: "The Proverbs, King James Version, 9:9" },
  { id: 'starter-0876', text: "The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.", creator: "Unknown", source: "The Proverbs, King James Version, 9:10" },
  { id: 'starter-0877', text: "For by me thy days shall be multiplied, and the years of thy life shall be increased.", creator: "Unknown", source: "The Proverbs, King James Version, 9:11" },
  { id: 'starter-0878', text: "If thou be wise, thou shalt be wise for thyself: but if thou scornest, thou alone shalt bear it.", creator: "Unknown", source: "The Proverbs, King James Version, 9:12" },
  { id: 'starter-0879', text: "For she sitteth at the door of her house, on a seat in the high places of the city,", creator: "Unknown", source: "The Proverbs, King James Version, 9:14" },
  { id: 'starter-0880', text: "To call passengers who go right on their ways:", creator: "Unknown", source: "The Proverbs, King James Version, 9:15" },
  { id: 'starter-0881', text: "Whoso is simple, let him turn in hither: and as for him that wanteth understanding, she saith to him,", creator: "Unknown", source: "The Proverbs, King James Version, 9:16" },
  { id: 'starter-0882', text: "Stolen waters are sweet, and bread eaten in secret is pleasant.", creator: "Unknown", source: "The Proverbs, King James Version, 9:17" },
  { id: 'starter-0883', text: "But he knoweth not that the dead are there; and that her guests are in the depths of hell.", creator: "Unknown", source: "The Proverbs, King James Version, 9:18" },
  { id: 'starter-0884', text: "The proverbs of Solomon. A wise son maketh a glad father: but a foolish son is the heaviness of his mother.", creator: "Unknown", source: "The Proverbs, King James Version, 10:1" },
  { id: 'starter-0885', text: "He becometh poor that dealeth with a slack hand: but the hand of the diligent maketh rich.", creator: "Unknown", source: "The Proverbs, King James Version, 10:4" },
  { id: 'starter-0886', text: "He that gathereth in summer is a wise son: but he that sleepeth in harvest is a son that causeth shame.", creator: "Unknown", source: "The Proverbs, King James Version, 10:5" },
  { id: 'starter-0887', text: "The wise in heart will receive commandments: but a prating fool shall fall.", creator: "Unknown", source: "The Proverbs, King James Version, 10:8" },
  { id: 'starter-0888', text: "He that walketh uprightly walketh surely: but he that perverteth his ways shall be known.", creator: "Unknown", source: "The Proverbs, King James Version, 10:9" },
  { id: 'starter-0889', text: "He that winketh with the eye causeth sorrow: but a prating fool shall fall.", creator: "Unknown", source: "The Proverbs, King James Version, 10:10" },
  { id: 'starter-0890', text: "Hatred stirreth up strifes: but love covereth all sins.", creator: "Unknown", source: "The Proverbs, King James Version, 10:12" },
  { id: 'starter-0891', text: "In the lips of him that hath understanding wisdom is found: but a rod is for the back of him that is void of understanding.", creator: "Unknown", source: "The Proverbs, King James Version, 10:13" },
  { id: 'starter-0892', text: "He is in the way of life that keepeth instruction: but he that refuseth reproof erreth.", creator: "Unknown", source: "The Proverbs, King James Version, 10:17" },
  { id: 'starter-0893', text: "He that hideth hatred with lying lips, and he that uttereth a slander, is a fool.", creator: "Unknown", source: "The Proverbs, King James Version, 10:18" },
  { id: 'starter-0894', text: "In the multitude of words there wanteth not sin: but he that refraineth his lips is wise.", creator: "Unknown", source: "The Proverbs, King James Version, 10:19" },
  { id: 'starter-0895', text: "The lips of the righteous feed many: but fools die for want of wisdom.", creator: "Unknown", source: "The Proverbs, King James Version, 10:21" },
  { id: 'starter-0896', text: "The blessing of the LORD, it maketh rich, and he addeth no sorrow with it.", creator: "Unknown", source: "The Proverbs, King James Version, 10:22" },
  { id: 'starter-0897', text: "It is as sport to a fool to do mischief: but a man of understanding hath wisdom.", creator: "Unknown", source: "The Proverbs, King James Version, 10:23" },
  { id: 'starter-0898', text: "As vinegar to the teeth, and as smoke to the eyes, so is the sluggard to them that send him.", creator: "Unknown", source: "The Proverbs, King James Version, 10:26" },
  { id: 'starter-0899', text: "The mouth of the just bringeth forth wisdom: but the froward tongue shall be cut out.", creator: "Unknown", source: "The Proverbs, King James Version, 10:31" },
  { id: 'starter-0900', text: "A false balance is abomination to the LORD: but a just weight is his delight.", creator: "Unknown", source: "The Proverbs, King James Version, 11:1" },
  { id: 'starter-0901', text: "When pride cometh, then cometh shame: but with the lowly is wisdom.", creator: "Unknown", source: "The Proverbs, King James Version, 11:2" },
  { id: 'starter-0902', text: "The righteousness of the upright shall deliver them: but transgressors shall be taken in their own naughtiness.", creator: "Unknown", source: "The Proverbs, King James Version, 11:6" },
  { id: 'starter-0903', text: "An hypocrite with his mouth destroyeth his neighbour: but through knowledge shall the just be delivered.", creator: "Unknown", source: "The Proverbs, King James Version, 11:9" },
  { id: 'starter-0904', text: "He that is void of wisdom despiseth his neighbour: but a man of understanding holdeth his peace.", creator: "Unknown", source: "The Proverbs, King James Version, 11:12" },
  { id: 'starter-0905', text: "A talebearer revealeth secrets: but he that is of a faithful spirit concealeth the matter.", creator: "Unknown", source: "The Proverbs, King James Version, 11:13" },
  { id: 'starter-0906', text: "Where no counsel is, the people fall: but in the multitude of counsellors there is safety.", creator: "Unknown", source: "The Proverbs, King James Version, 11:14" },
  { id: 'starter-0907', text: "He that is surety for a stranger shall smart for it: and he that hateth suretiship is sure.", creator: "Unknown", source: "The Proverbs, King James Version, 11:15" },
  { id: 'starter-0908', text: "A gracious woman retaineth honour: and strong men retain riches.", creator: "Unknown", source: "The Proverbs, King James Version, 11:16" },
  { id: 'starter-0909', text: "The merciful man doeth good to his own soul: but he that is cruel troubleth his own flesh.", creator: "Unknown", source: "The Proverbs, King James Version, 11:17" },
  { id: 'starter-0910', text: "As righteousness tendeth to life: so he that pursueth evil pursueth it to his own death.", creator: "Unknown", source: "The Proverbs, King James Version, 11:19" },
  { id: 'starter-0911', text: "They that are of a froward heart are abomination to the LORD: but such as are upright in their way are his delight.", creator: "Unknown", source: "The Proverbs, King James Version, 11:20" },
  { id: 'starter-0912', text: "As a jewel of gold in a swine's snout, so is a fair woman which is without discretion.", creator: "Unknown", source: "The Proverbs, King James Version, 11:22" },
  { id: 'starter-0913', text: "There is that scattereth, and yet increaseth; and there is that withholdeth more than is meet, but it tendeth to poverty.", creator: "Unknown", source: "The Proverbs, King James Version, 11:24" },
  { id: 'starter-0914', text: "The liberal soul shall be made fat: and he that watereth shall be watered also himself.", creator: "Unknown", source: "The Proverbs, King James Version, 11:25" },
  { id: 'starter-0915', text: "He that diligently seeketh good procureth favour: but he that seeketh mischief, it shall come unto him.", creator: "Unknown", source: "The Proverbs, King James Version, 11:27" },
  { id: 'starter-0916', text: "He that trusteth in his riches shall fall; but the righteous shall flourish as a branch.", creator: "Unknown", source: "The Proverbs, King James Version, 11:28" },
  { id: 'starter-0917', text: "He that troubleth his own house shall inherit the wind: and the fool shall be servant to the wise of heart.", creator: "Unknown", source: "The Proverbs, King James Version, 11:29" },
  { id: 'starter-0918', text: "The fruit of the righteous is a tree of life; and he that winneth souls is wise.", creator: "Unknown", source: "The Proverbs, King James Version, 11:30" },
  { id: 'starter-0919', text: "Whoso loveth instruction loveth knowledge: but he that hateth reproof is brutish.", creator: "Unknown", source: "The Proverbs, King James Version, 12:1" },
  { id: 'starter-0920', text: "A virtuous woman is a crown to her husband: but she that maketh ashamed is as rottenness in his bones.", creator: "Unknown", source: "The Proverbs, King James Version, 12:4" },
  { id: 'starter-0921', text: "A man shall be commended according to his wisdom: but he that is of a perverse heart shall be despised.", creator: "Unknown", source: "The Proverbs, King James Version, 12:8" },
  { id: 'starter-0922', text: "He that is despised, and hath a servant, is better than he that honoureth himself, and lacketh bread.", creator: "Unknown", source: "The Proverbs, King James Version, 12:9" },
  { id: 'starter-0923', text: "He that tilleth his land shall be satisfied with bread: but he that followeth vain persons is void of understanding.", creator: "Unknown", source: "The Proverbs, King James Version, 12:11" },
  { id: 'starter-0924', text: "A man shall be satisfied with good by the fruit of his mouth: and the recompence of a man's hands shall be rendered unto him.", creator: "Unknown", source: "The Proverbs, King James Version, 12:14" },
  { id: 'starter-0925', text: "The way of a fool is right in his own eyes: but he that hearkeneth unto counsel is wise.", creator: "Unknown", source: "The Proverbs, King James Version, 12:15" },
  { id: 'starter-0926', text: "He that speaketh truth sheweth forth righteousness: but a false witness deceit.", creator: "Unknown", source: "The Proverbs, King James Version, 12:17" },
  { id: 'starter-0927', text: "There is that speaketh like the piercings of a sword: but the tongue of the wise is health.", creator: "Unknown", source: "The Proverbs, King James Version, 12:18" },
  { id: 'starter-0928', text: "The lip of truth shall be established for ever: but a lying tongue is but for a moment.", creator: "Unknown", source: "The Proverbs, King James Version, 12:19" },
  { id: 'starter-0929', text: "Deceit is in the heart of them that imagine evil: but to the counsellors of peace is joy.", creator: "Unknown", source: "The Proverbs, King James Version, 12:20" },
  { id: 'starter-0930', text: "Lying lips are abomination to the LORD: but they that deal truly are his delight.", creator: "Unknown", source: "The Proverbs, King James Version, 12:22" },
  { id: 'starter-0931', text: "A prudent man concealeth knowledge: but the heart of fools proclaimeth foolishness.", creator: "Unknown", source: "The Proverbs, King James Version, 12:23" },
  { id: 'starter-0932', text: "The hand of the diligent shall bear rule: but the slothful shall be under tribute.", creator: "Unknown", source: "The Proverbs, King James Version, 12:24" },
  { id: 'starter-0933', text: "Heaviness in the heart of man maketh it stoop: but a good word maketh it glad.", creator: "Unknown", source: "The Proverbs, King James Version, 12:25" },
  { id: 'starter-0934', text: "The slothful man roasteth not that which he took in hunting: but the substance of a diligent man is precious.", creator: "Unknown", source: "The Proverbs, King James Version, 12:27" },
  { id: 'starter-0935', text: "In the way of righteousness is life: and in the pathway thereof there is no death.", creator: "Unknown", source: "The Proverbs, King James Version, 12:28" },
  { id: 'starter-0936', text: "A wise son heareth his father's instruction: but a scorner heareth not rebuke.", creator: "Unknown", source: "The Proverbs, King James Version, 13:1" },
  { id: 'starter-0937', text: "A man shall eat good by the fruit of his mouth: but the soul of the transgressors shall eat violence.", creator: "Unknown", source: "The Proverbs, King James Version, 13:2" },
  { id: 'starter-0938', text: "The soul of the sluggard desireth, and hath nothing: but the soul of the diligent shall be made fat.", creator: "Unknown", source: "The Proverbs, King James Version, 13:4" },
  { id: 'starter-0939', text: "There is that maketh himself rich, yet hath nothing: there is that maketh himself poor, yet hath great riches.", creator: "Unknown", source: "The Proverbs, King James Version, 13:7" },
  { id: 'starter-0940', text: "The ransom of a man's life are his riches: but the poor heareth not rebuke.", creator: "Unknown", source: "The Proverbs, King James Version, 13:8" },
  { id: 'starter-0941', text: "Only by pride cometh contention: but with the well advised is wisdom.", creator: "Unknown", source: "The Proverbs, King James Version, 13:10" },
  { id: 'starter-0942', text: "Wealth gotten by vanity shall be diminished: but he that gathereth by labour shall increase.", creator: "Unknown", source: "The Proverbs, King James Version, 13:11" },
  { id: 'starter-0943', text: "Hope deferred maketh the heart sick: but when the desire cometh, it is a tree of life.", creator: "Unknown", source: "The Proverbs, King James Version, 13:12" },
  { id: 'starter-0944', text: "Whoso despiseth the word shall be destroyed: but he that feareth the commandment shall be rewarded.", creator: "Unknown", source: "The Proverbs, King James Version, 13:13" },
  { id: 'starter-0945', text: "The law of the wise is a fountain of life, to depart from the snares of death.", creator: "Unknown", source: "The Proverbs, King James Version, 13:14" },
  { id: 'starter-0946', text: "Good understanding giveth favour: but the way of transgressors is hard.", creator: "Unknown", source: "The Proverbs, King James Version, 13:15" },
  { id: 'starter-0947', text: "Every prudent man dealeth with knowledge: but a fool layeth open his folly.", creator: "Unknown", source: "The Proverbs, King James Version, 13:16" },
  { id: 'starter-0948', text: "Poverty and shame shall be to him that refuseth instruction: but he that regardeth reproof shall be honoured.", creator: "Unknown", source: "The Proverbs, King James Version, 13:18" },
  { id: 'starter-0949', text: "The desire accomplished is sweet to the soul: but it is abomination to fools to depart from evil.", creator: "Unknown", source: "The Proverbs, King James Version, 13:19" },
  { id: 'starter-0950', text: "He that walketh with wise men shall be wise: but a companion of fools shall be destroyed.", creator: "Unknown", source: "The Proverbs, King James Version, 13:20" },
  { id: 'starter-0951', text: "Much food is in the tillage of the poor: but there is that is destroyed for want of judgment.", creator: "Unknown", source: "The Proverbs, King James Version, 13:23" },
  { id: 'starter-0952', text: "He that spareth his rod hateth his son: but he that loveth him chasteneth him betimes.", creator: "Unknown", source: "The Proverbs, King James Version, 13:24" },
  { id: 'starter-0953', text: "Every wise woman buildeth her house: but the foolish plucketh it down with her hands.", creator: "Unknown", source: "The Proverbs, King James Version, 14:1" },
  { id: 'starter-0954', text: "He that walketh in his uprightness feareth the LORD: but he that is perverse in his ways despiseth him.", creator: "Unknown", source: "The Proverbs, King James Version, 14:2" },
  { id: 'starter-0955', text: "In the mouth of the foolish is a rod of pride: but the lips of the wise shall preserve them.", creator: "Unknown", source: "The Proverbs, King James Version, 14:3" },
  { id: 'starter-0956', text: "Where no oxen are, the crib is clean: but much increase is by the strength of the ox.", creator: "Unknown", source: "The Proverbs, King James Version, 14:4" },
  { id: 'starter-0957', text: "A faithful witness will not lie: but a false witness will utter lies.", creator: "Unknown", source: "The Proverbs, King James Version, 14:5" },
  { id: 'starter-0958', text: "A scorner seeketh wisdom, and findeth it not: but knowledge is easy unto him that understandeth.", creator: "Unknown", source: "The Proverbs, King James Version, 14:6" },
  { id: 'starter-0959', text: "Go from the presence of a foolish man, when thou perceivest not in him the lips of knowledge.", creator: "Unknown", source: "The Proverbs, King James Version, 14:7" },
  { id: 'starter-0960', text: "The wisdom of the prudent is to understand his way: but the folly of fools is deceit.", creator: "Unknown", source: "The Proverbs, King James Version, 14:8" },
  { id: 'starter-0961', text: "Fools make a mock at sin: but among the righteous there is favour.", creator: "Unknown", source: "The Proverbs, King James Version, 14:9" },
  { id: 'starter-0962', text: "The heart knoweth his own bitterness; and a stranger doth not intermeddle with his joy.", creator: "Unknown", source: "The Proverbs, King James Version, 14:10" },
  { id: 'starter-0963', text: "There is a way which seemeth right unto a man, but the end thereof are the ways of death.", creator: "Unknown", source: "The Proverbs, King James Version, 14:12" },
  { id: 'starter-0964', text: "Even in laughter the heart is sorrowful; and the end of that mirth is heaviness.", creator: "Unknown", source: "The Proverbs, King James Version, 14:13" },
  { id: 'starter-0965', text: "The backslider in heart shall be filled with his own ways: and a good man shall be satisfied from himself.", creator: "Unknown", source: "The Proverbs, King James Version, 14:14" },
  { id: 'starter-0966', text: "The simple believeth every word: but the prudent man looketh well to his going.", creator: "Unknown", source: "The Proverbs, King James Version, 14:15" },
  { id: 'starter-0967', text: "A wise man feareth, and departeth from evil: but the fool rageth, and is confident.", creator: "Unknown", source: "The Proverbs, King James Version, 14:16" },
  { id: 'starter-0968', text: "The simple inherit folly: but the prudent are crowned with knowledge.", creator: "Unknown", source: "The Proverbs, King James Version, 14:18" },
  { id: 'starter-0969', text: "The poor is hated even of his own neighbour: but the rich hath many friends.", creator: "Unknown", source: "The Proverbs, King James Version, 14:20" },
  { id: 'starter-0970', text: "He that despiseth his neighbour sinneth: but he that hath mercy on the poor, happy is he.", creator: "Unknown", source: "The Proverbs, King James Version, 14:21" },
  { id: 'starter-0971', text: "Do they not err that devise evil? but mercy and truth shall be to them that devise good.", creator: "Unknown", source: "The Proverbs, King James Version, 14:22" },
  { id: 'starter-0972', text: "In all labour there is profit: but the talk of the lips tendeth only to penury.", creator: "Unknown", source: "The Proverbs, King James Version, 14:23" },
  { id: 'starter-0973', text: "The crown of the wise is their riches: but the foolishness of fools is folly.", creator: "Unknown", source: "The Proverbs, King James Version, 14:24" },
  { id: 'starter-0974', text: "A true witness delivereth souls: but a deceitful witness speaketh lies.", creator: "Unknown", source: "The Proverbs, King James Version, 14:25" },
  { id: 'starter-0975', text: "In the fear of the LORD is strong confidence: and his children shall have a place of refuge.", creator: "Unknown", source: "The Proverbs, King James Version, 14:26" },
  { id: 'starter-0976', text: "The fear of the LORD is a fountain of life, to depart from the snares of death.", creator: "Unknown", source: "The Proverbs, King James Version, 14:27" },
  { id: 'starter-0977', text: "A sound heart is the life of the flesh: but envy the rottenness of the bones.", creator: "Unknown", source: "The Proverbs, King James Version, 14:30" },
  { id: 'starter-0978', text: "He that oppresseth the poor reproacheth his Maker: but he that honoureth him hath mercy on the poor.", creator: "Unknown", source: "The Proverbs, King James Version, 14:31" },
  { id: 'starter-0979', text: "Wisdom resteth in the heart of him that hath understanding: but that which is in the midst of fools is made known.", creator: "Unknown", source: "The Proverbs, King James Version, 14:33" },
  { id: 'starter-0980', text: "Righteousness exalteth a nation: but sin is a reproach to any people.", creator: "Unknown", source: "The Proverbs, King James Version, 14:34" },
  { id: 'starter-0981', text: "The tongue of the wise useth knowledge aright: but the mouth of fools poureth out foolishness.", creator: "Unknown", source: "The Proverbs, King James Version, 15:2" },
  { id: 'starter-0982', text: "The eyes of the LORD are in every place, beholding the evil and the good.", creator: "Unknown", source: "The Proverbs, King James Version, 15:3" },
  { id: 'starter-0983', text: "A wholesome tongue is a tree of life: but perverseness therein is a breach in the spirit.", creator: "Unknown", source: "The Proverbs, King James Version, 15:4" },
  { id: 'starter-0984', text: "A fool despiseth his father's instruction: but he that regardeth reproof is prudent.", creator: "Unknown", source: "The Proverbs, King James Version, 15:5" },
  { id: 'starter-0985', text: "The lips of the wise disperse knowledge: but the heart of the foolish doeth not so.", creator: "Unknown", source: "The Proverbs, King James Version, 15:7" },
  { id: 'starter-0986', text: "Correction is grievous unto him that forsaketh the way: and he that hateth reproof shall die.", creator: "Unknown", source: "The Proverbs, King James Version, 15:10" },
  { id: 'starter-0987', text: "A scorner loveth not one that reproveth him: neither will he go unto the wise.", creator: "Unknown", source: "The Proverbs, King James Version, 15:12" },
  { id: 'starter-0988', text: "A merry heart maketh a cheerful countenance: but by sorrow of the heart the spirit is broken.", creator: "Unknown", source: "The Proverbs, King James Version, 15:13" },
  { id: 'starter-0989', text: "The heart of him that hath understanding seeketh knowledge: but the mouth of fools feedeth on foolishness.", creator: "Unknown", source: "The Proverbs, King James Version, 15:14" },
  { id: 'starter-0990', text: "All the days of the afflicted are evil: but he that is of a merry heart hath a continual feast.", creator: "Unknown", source: "The Proverbs, King James Version, 15:15" },
  { id: 'starter-0991', text: "Better is little with the fear of the LORD than great treasure and trouble therewith.", creator: "Unknown", source: "The Proverbs, King James Version, 15:16" },
  { id: 'starter-0992', text: "Better is a dinner of herbs where love is, than a stalled ox and hatred therewith.", creator: "Unknown", source: "The Proverbs, King James Version, 15:17" },
  { id: 'starter-0993', text: "A wrathful man stirreth up strife: but he that is slow to anger appeaseth strife.", creator: "Unknown", source: "The Proverbs, King James Version, 15:18" },
  { id: 'starter-0994', text: "The way of the slothful man is as an hedge of thorns: but the way of the righteous is made plain.", creator: "Unknown", source: "The Proverbs, King James Version, 15:19" },
  { id: 'starter-0995', text: "A wise son maketh a glad father: but a foolish man despiseth his mother.", creator: "Unknown", source: "The Proverbs, King James Version, 15:20" },
  { id: 'starter-0996', text: "Folly is joy to him that is destitute of wisdom: but a man of understanding walketh uprightly.", creator: "Unknown", source: "The Proverbs, King James Version, 15:21" },
  { id: 'starter-0997', text: "Without counsel purposes are disappointed: but in the multitude of counsellors they are established.", creator: "Unknown", source: "The Proverbs, King James Version, 15:22" },
  { id: 'starter-0998', text: "A man hath joy by the answer of his mouth: and a word spoken in due season, how good is it!", creator: "Unknown", source: "The Proverbs, King James Version, 15:23" },
  { id: 'starter-0999', text: "The way of life is above to the wise, that he may depart from hell beneath.", creator: "Unknown", source: "The Proverbs, King James Version, 15:24" },
  { id: 'starter-1000', text: "He that is greedy of gain troubleth his own house; but he that hateth gifts shall live.", creator: "Unknown", source: "The Proverbs, King James Version, 15:27" },
] as const;

if (starterQuotes.length !== 1000) {
  throw new Error(`Expected 1,000 bundled starter quotes; found ${starterQuotes.length}.`);
}
